/* DAWAH X — ahmad, অধ্যায় 120 · খণ্ড 120 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][120]=[[23801,23801,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏إِبْرَاهِيمَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ جُنُبًا فَأَرَادَ أَنْ يَنَامَ أَوْ يَأْكُلَ تَوَضَّأَ ‏","","",""],[23802,23802,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏أَنَّ ‏ ‏عَلْقَمَةَ ‏ ‏وَشُرَيْحَ بْنَ أَرْطَاةَ ‏ ‏كَانَا عِنْدَ ‏ ‏عَائِشَةَ ‏ ‏فَقَالَ ‏ ‏أَحَدُهُمَا ‏ ‏سَلْهَا عَنْ الْقُبْلَةِ لِلصَّائِمِ فَقَالَ أَحَدُهُمَا لَا أَرْفُثُ عِنْدَ أُمِّ الْمُؤْمِنِينَ فَقَالَتْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَبِّلُ وَهُوَ صَائِمٌ ‏ ‏وَيُبَاشِرُ ‏ ‏وَهُوَ صَائِمٌ وَكَانَ أَمْلَكَكُمْ ‏ ‏لِإِرْبِهِ ‏","","",""],[23803,23803,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏وَلَدُ الرَّجُلِ ‏ ‏مِنْ كَسْبِهِ مِنْ أَطْيَبِ كَسْبِهِ فَكُلُوا مِنْ أَمْوَالِهِمْ هَنِيئًا ‏","","",""],[23804,23804,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏دَخَلَ عَلَيْهَا وَعِنْدَهَا ‏ ‏جَارِيَتَانِ ‏ ‏تَضْرِبَانِ بِدُفَّيْنِ ‏ ‏فَانْتَهَرَهُمَا ‏ ‏أَبُو بَكْرٍ ‏ ‏فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعْهُنَّ فَإِنَّ لِكُلِّ قَوْمٍ عِيدًا ‏","","",""],[23805,23805,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏أَخْبَرَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا كَانَتْ ‏ ‏تَغْتَسِلُ هِيَ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ ‏","","",""],[23806,23806,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْمِقْدَامِ بْنِ شُرَيْحِ بْنِ هَانِئٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏كُنْتُ ‏ ‏أَتَعَرَّقُ ‏ ‏الْعَرْقَ ‏ ‏وَأَنَا حَائِضٌ فَيَأْخُذُهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَضَعُ فَمَهُ حَيْثُ كَانَ فَمِي وَأَشْرَبُ مِنْ الْإِنَاءِ فَيَأْخَذُهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَضَعُ فَمَهُ حَيْثُ كَانَ فَمِي وَأَنَا حَائِضٌ ‏","","",""],[23807,23807,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏مَا رَأَيْتُهُ كَانَ يُفَضِّلُ لَيْلَةً عَلَى لَيْلَةٍ ‏","","",""],[23808,23808,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الشَّعْبِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏قَالَ سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ الرَّجُلِ يَبْعَثُ ‏ ‏بِهَدْيِهِ ‏ ‏هَلْ يُمْسِكُ عَمَّا يُمْسِكُ عَنْهُ الْمُحْرِمُ قَالَ فَسَمِعْتُ صَوْتَ يَدَيْهَا مِنْ وَرَاءِ الْحِجَابِ ثُمَّ قَالَتْ قَدْ كُنْتُ ‏ ‏أَفْتِلُ ‏ ‏قَلَائِدَ ‏ ‏هَدْيِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ يُرْسِلُ بِهِنَّ ثُمَّ لَا يَحْرُمُ مِنْهُ شَيْءٌ ‏","","",""],[23809,23809,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَمَّةٍ ‏ ‏لَهُ ‏ ‏سَأَلَتْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ يَتِيمٍ فِي حِجْرِهَا فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَطْيَبَ مَا أَكَلَ الرَّجُلُ مِنْ كَسْبِهِ وَإِنَّ وَلَدَهُ مِنْ كَسْبِهِ ‏","","",""],[23810,23810,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏بَكَّارٌ يَعْنِي ابْنَ عَبْدِ اللَّهِ بْنِ وَهْبٍ الصَّنْعَانِيَّ ‏ ‏فَذَكَرَ ‏ ‏حَدِيثًا ‏ ‏قَالَ وَسَمِعْتُ ‏ ‏ابْنَ أَبِي مُلَيْكَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حُوسِبَ عُذِّبَ قَالَتْ فَقُلْتُ أَرَأَيْتَ قَوْلَهُ عَزَّ وَجَلَّ ‏ { ‏يُحَاسَبُ حِسَابًا يَسِيرًا ‏} ‏قَالَ إِنَّمَا ‏ ‏ذَاكُمْ الْعَرْضُ وَلَكِنْ مَنْ نُوقِشَ الْحِسَابَ عُذِّبَ ‏","","",""],[23811,23811,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏اشْتَكَى ‏ ‏أَحَدٌ مَسَحَهُ بِيَمِينِهِ ثُمَّ قَالَ ‏ ‏أَذْهِبْ ‏ ‏الْبَاسَ ‏ ‏رَبَّ النَّاسِ وَاشْفِ وَأَنْتَ الشَّافِي لَا شِفَاءَ إِلَّا شِفَاؤُكَ شِفَاءً لَا ‏ ‏يُغَادِرُ ‏ ‏سَقَمًا ‏","","",""],[23812,23812,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏لَمَّا أَنْزَلَ اللَّهُ تَبَارَكَ وَتَعَالَى الْآيَاتِ آيَاتِ الرِّبَا مِنْ آخِرِ سُورَةِ ‏ ‏الْبَقَرَةِ ‏ ‏قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَرَأَهُنَّ عَلَيْنَا ثُمَّ ‏ ‏حَرَّمَ التِّجَارَةَ فِي الْخَمْرِ ‏","","",""],[23813,23813,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَقْرَأُ فِي شَيْءٍ مِنْ صَلَاةِ اللَّيْلِ جَالِسًا حَتَّى دَخَلَ فِي السِّنِّ وَكَانَ إِذَا بَقِيَتْ عَلَيْهِ ثَلَاثُونَ آيَةً أَوْ أَرْبَعُونَ قَامَ فَقَرَأَهَا ثُمَّ سَجَدَ ‏","","",""],[23814,23814,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَابِسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَابِسِ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَ ‏ ‏سَأَلْنَاهَا أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ تُؤْكَلَ لُحُومُ الْأَضَاحِيِّ بَعْدَ ثَلَاثٍ فَقَالَتْ مَا قَالَهُ إِلَّا فِي عَامٍ جَاعَ النَّاسُ فِيهِ فَأَرَادَ ‏ ‏أَنْ يُطْعِمَ الْغَنِيُّ الْفَقِيرَ وَقَدْ كُنَّا نَرْفَعُ الْكُرَاعَ فَنَأْكُلُهَا بَعْدَ خَمْسَ عَشْرَةَ قُلْتُ فَمَا اضْطَرَّكُمْ إِلَى ذَلِكَ قَالَ فَضَحِكَتْ وَقَالَتْ ‏ ‏مَا شَبِعَ آلُ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ خُبْزٍ مَأْدُومٍ ثَلَاثَ لَيَالٍ حَتَّى لَحِقَ بِاللَّهِ عَزَّ وَجَلَّ ‏","","",""],[23815,23815,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورِ ابْنِ صَفِيَّةَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏تُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ شَبِعْنَا مِنْ ‏ ‏الْأَسْوَدَيْنِ ‏ ‏التَّمْرِ وَالْمَاءِ ‏","","",""],[23816,23816,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ الْأَقْمَرِ ‏ ‏عَنْ ‏ ‏أَبِي حُذَيْفَةَ ‏ ‏رَجُلٍ مِنْ أَصْحَابِ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏ذَهَبْتُ ‏ ‏أَحْكِي امْرَأَةً ‏ ‏أَوْ رَجُلًا ‏ ‏عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أُحِبُّ أَنْ حَكَيْتُ أَحَدًا وَأَنَّ لِي كَذَا وَكَذَا ‏ ‏أَعْظَمَ ‏","","",""],[23817,23817,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ عَطَاءٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ بْنِ يَزِيدَ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏أَيُبَاشِرُ الصَّائِمُ ‏ ‏يَعْنِي امْرَأَتَهُ ‏ ‏قَالَتْ لَا قُلْتُ ‏ ‏أَلَيْسَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ كَانَ ‏ ‏يُبَاشِرُ ‏ ‏وَهُوَ صَائِمٌ قَالَتْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمْلَكَكُمْ ‏ ‏لِإِرْبِهِ ‏","","",""],[23818,23818,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَأَنِّي أَنْظُرُ إِلَى ‏ ‏وَبِيصِ ‏ ‏الطِّيبِ فِي مَفْرِقِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُحْرِمٌ ‏","","",""],[23819,23819,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏حَدَّثَتْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَكُنْ يَصُومُ مِنْ شَهْرٍ مِنْ السَّنَةِ أَكْثَرَ مِنْ صِيَامِهِ مِنْ شَعْبَانَ فَإِنَّهُ كَانَ يَصُومُ شَعْبَانَ كُلَّهُ وَكَانَ يَقُولُ ‏ ‏خُذُوا مِنْ الْعَمَلِ مَا تُطِيقُونَ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ لَا يَمَلُّ حَتَّى تَمَلُّوا فَإِنَّهُ كَانَ أَحَبُّ الصَّلَاةِ إِلَيْهِ مَا دَاوَمَ عَلَيْهَا وَإِنْ قَلَّ وَكَانَ إِذَا صَلَّى صَلَاةً يُدَاوِمُ عَلَيْهَا ‏","","",""],[23820,23820,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏عَائِشَةُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي رَكْعَتَيْنِ بَيْنَ النِّدَاءِ وَالْإِقَامَةِ مِنْ صَلَاةِ الصُّبْحِ ‏","","",""],[23821,23821,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏هَلْ كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْقُدُ وَهُوَ جُنُبٌ قَالَتْ نَعَمْ وَيَتَوَضَّأُ وُضُوءَهُ لِلصَّلَاةِ ‏","","",""],[23822,23822,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَطَاءٌ الْخُرَاسَانِيُّ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ أَبِي بَكْرٍ ‏ ‏دَخَلَ عَلَى ‏ ‏عَائِشَةَ ‏ ‏يَوْمَ ‏ ‏عَرَفَةَ ‏ ‏وَهِيَ صَائِمَةٌ وَالْمَاءُ يُرَشُّ عَلَيْهَا فَقَالَ لَهَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏أَفْطِرِي فَقَالَتْ أُفْطِرُ وَقَدْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِنَّ ‏ ‏صَوْمَ يَوْمِ ‏ ‏عَرَفَةَ ‏ ‏يُكَفِّرُ الْعَامَ الَّذِي قَبْلَهُ ‏","","",""],[23823,23823,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهَا ‏ ‏رَأَيْتُكِ فِي الْمَنَامِ مَرَّتَيْنِ إِذَا رَجُلٌ يَحْمِلُكِ فِي ‏ ‏سَرَقَةٍ ‏ ‏مِنْ حَرِيرٍ فَيَقُولُ هَذِهِ امْرَأَتُكَ فَأَكْشِفُ عَنْهَا فَإِذَا هِيَ أَنْتِ فَأَقُولُ إِنْ يَكُ هَذَا مِنْ عِنْدِ اللَّهِ عَزَّ وَجَلَّ ‏ ‏يُمْضِهِ ‏","","",""],[23824,23824,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ الْحَجَّاجِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏أُمَّ حَبِيبَةَ بِنْتَ جَحْشٍ ‏ ‏كَانَتْ تَحْتَ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏وَأَنَّهَا ‏ ‏اسْتُحِيضَتْ ‏ ‏فَلَا تَطْهُرُ فَذُكِرَ شَأْنُهَا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لَيْسَتْ بِالْحَيْضَةِ وَلَكِنَّهَا ‏ ‏رَكْضَةٌ ‏ ‏مِنْ الرَّحِمِ فَلْتَنْظُرْ قَدْرَ ‏ ‏قُرْئِهَا ‏ ‏الَّتِي كَانَتْ تَحِيضُ لَهُ فَلْتَتْرُكْ الصَّلَاةَ ثُمَّ لِتَنْظُرْ مَا بَعْدَ ذَلِكَ فَلْتَغْتَسِلْ عِنْدَ كُلِّ صَلَاةٍ وَلْتُصَلِّ ‏","","",""],[23825,23825,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ الْحَجَّاجِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا رَأَى الْمَطَرَ قَالَ اللَّهُمَّ صَيِّبًا هَنِيئًا ‏","","",""],[23826,23826,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏وَأَبِي حَصِينٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ وَثَّابٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏قَالَ سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ وَتْرِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ ‏ ‏مِنْ كُلِّ اللَّيْلِ قَدْ أَوْتَرَ وَسَطَهُ وَآخِرَهُ وَأَوَّلَهُ فَانْتَهَى وِتْرُهُ إِلَى ‏ ‏السَّحَرِ ‏ ‏حَتَّى مَاتَ ‏","","",""],[23827,23827,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏اخْتَصَمَ ‏ ‏سَعْدُ بْنُ أَبِي وَقَّاصٍ ‏ ‏وَعَبْدُ بْنُ زَمْعَةَ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏سَعْدٌ ‏ ‏يَا رَسُولَ اللَّهِ ابْنُ أَخِي ‏ ‏عُتْبَةَ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَهِدَ ‏ ‏إِلَيَّ أَنَّهُ ابْنُهُ انْظُرْ إِلَى شَبَهِهِ وَقَالَ ‏ ‏عَبْدُ بْنُ زَمْعَةَ ‏ ‏هَذَا أَخِي يَا رَسُولَ اللَّهِ وُلِدَ عَلَى فِرَاشِ أَبِي فَنَظَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى شَبَهِهِ فَرَأَى شَبَهًا بَيِّنًا ‏ ‏بِعُتْبَةَ ‏ ‏فَقَالَ هُوَ لَكَ يَا ‏ ‏عَبْدُ بْنَ زَمْعَةَ ‏ ‏الْوَلَدُ لِلْفِرَاشِ ‏ ‏وَلِلْعَاهِرِ ‏ ‏الْحَجَرُ وَاحْتَجِبِي مِنْهُ يَا ‏ ‏سَوْدَةُ ابْنَةَ زَمْعَةَ ‏ ‏قَالَتْ فَلَمْ يَرَ ‏ ‏سَوْدَةَ ‏ ‏قَطُّ ‏","","",""],[23828,23828,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ الطُّفَاوِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَبْعَثُ ‏ ‏بِالْهَدْيِ ‏ ‏ثُمَّ لَا يَصْنَعُ مَا يَصْنَعُ الْمُحْرِمُ ‏","","",""],[23829,23829,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَبْدِ الرَّحْمَنِ الْجُمَحِيُّ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَبْقَى بَعْدِي مِنْ النُّبُوَّةِ شَيْءٌ إِلَّا الْمُبَشِّرَاتُ قَالُوا يَا رَسُولَ اللَّهِ وَمَا الْمُبَشِّرَاتُ قَالَ الرُّؤْيَا الصَّالِحَةُ يَرَاهَا الرَّجُلُ أَوْ تُرَى لَهُ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَقَدْ ‏ ‏سَمِعْتُ مِنْ ‏ ‏يَحْيَى بْنِ أَيُّوبَ ‏ ‏هَذَا الْحَدِيثَ غَيْرَ مَرَّةٍ ‏ ‏حَدَّثَنَاهُ ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏أَمْلَاهُ عَلَيْنَا إِمْلَاءً قَالَ حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَبْدِ الرَّحْمَنِ الْجُمَحِيُّ ‏ ‏مِثْلَهُ ‏","","",""],[23830,23830,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ مَرْوَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ وَإِنَّا لَجُنُبَانِ وَلَكِنَّ الْمَاءَ لَا يَجْنُبُ ‏","","",""],[23831,23831,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَرِهَ الصَّلَاةَ فِي ‏ ‏مَلَاحِفِ ‏ ‏النِّسَاءِ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏وَحَدَّثَنِي ‏ ‏إِمَّا ‏ ‏قَالَ ‏ ‏كَثِيرٌ ‏ ‏وَإِمَّا ‏ ‏قَالَ ‏ ‏عَبْدُ رَبِّهِ ‏ ‏شَكَّ ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏أَبِي عِيَاضٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى وَعَلَيْهِ ‏ ‏مِرْطٌ ‏ ‏مِنْ صُوفٍ ‏ ‏لِعَائِشَةَ ‏ ‏عَلَيْهَا بَعْضُهُ وَعَلَيْهِ بَعْضُهُ ‏","","",""],[23832,23832,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏اللَّهُمَّ اجْعَلْنِي مِنْ الَّذِينَ إِذَا أَحْسَنُوا اسْتَبْشَرُوا وَإِذَا أَسَاءُوا اسْتَغْفَرُوا ‏","","",""],[23833,23833,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سَابَقَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَبَقْتُهُ ‏","","",""],[23834,23834,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْكِرْمَانِيُّ حَسَّانُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ أَبِي بُرْدَةَ بْنِ أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏عَائِشَةَ ‏ ‏فَقُلْتُ ‏ ‏يَا أُمَّتَاهُ حَدِّثِينِي ‏ ‏شَيْئًا ‏ ‏سَمِعْتِيهِ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الطَّيْرُ ‏ ‏تَجْرِي بِقَدَرٍ وَكَانَ يُعْجِبُهُ الْفَأْلُ الْحَسَنُ ‏","","",""],[23835,23835,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَأَنِّي أَنْظُرُ إِلَى ‏ ‏وَبِيصِهِ ‏ ‏وَبِيصُ ‏ ‏الطِّيبِ فِي مَفْرِقِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُحْرِمٌ ‏","","",""],[23836,23836,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏مُعَاذَةُ الْعَدَوِيَّةُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مُرْنَ أَزْوَاجَكُنَّ أَنْ يَغْسِلُوا عَنْهُمْ أَثَرَ الْخَلَاءِ وَالْبَوْلِ فَإِنِّي أَسْتَحِي أَنْ آمُرَهُمْ بِذَلِكَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَفْعَلُهُ ‏","","",""],[23837,23837,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏وَنُعْمَانُ ‏ ‏أَوْ أَحَدُهُمَا ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُسْلِمًا مِنْ لَعْنَةٍ تُذْكَرُ وَلَا انْتَقَمَ لِنَفْسِهِ شَيْئًا يُؤْتَى إِلَيْهِ إِلَّا أَنْ تُنْتَهَكَ حُرُمَاتُ اللَّهِ عَزَّ وَجَلَّ وَلَا ضَرَبَ بِيَدِهِ شَيْئًا قَطُّ إِلَّا أَنْ يَضْرِبَ بِهَا فِي سَبِيلِ اللَّهِ وَلَا سُئِلَ شَيْئًا قَطُّ فَمَنَعَهُ إِلَّا أَنْ يُسْأَلَ مَأْثَمًا فَإِنَّهُ كَانَ أَبْعَدَ النَّاسِ مِنْهُ وَلَا خُيِّرَ بَيْنَ أَمْرَيْنِ قَطُّ إِلَّا اخْتَارَ أَيْسَرَهُمَا وَكَانَ إِذَا كَانَ حَدِيثَ عَهْدٍ ‏ ‏بِجِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏يُدَارِسُهُ كَانَ أَجْوَدَ بِالْخَيْرِ مِنْ الرِّيحِ الْمُرْسَلَةِ ‏","","",""],[23838,23838,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سُلَيْمُ بْنُ أَخْضَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أُمِّ مُحَمَّدٍ امْرَأَةِ أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَتْ عِنْدَنَا ‏ ‏أُمُّ سَلَمَةَ ‏ ‏فَجَاءَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ جُنْحِ اللَّيْلِ قَالَتْ فَذَكَرْتُ شَيْئًا صَنَعَهُ بِيَدِهِ قَالَتْ وَجَعَلَ لَا يَفْطِنُ ‏ ‏لِأُمِّ سَلَمَةَ ‏ ‏قَالَتْ وَجَعَلْتُ ‏ ‏أُومِئُ ‏ ‏إِلَيْهِ حَتَّى فَطَنَ قَالَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏أَهَكَذَا الْآنَ أَمَا كَانَتْ وَاحِدَةٌ مِنَّا عِنْدَكَ إِلَّا فِي ‏ ‏خِلَابَةٍ ‏ ‏كَمَا أَرَى وَسَبَّتْ ‏ ‏عَائِشَةَ ‏ ‏وَجَعَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَاهَا ‏ ‏فَتَأْبَى فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُبِّيهَا فَسَبَّتْهَا حَتَّى غَلَبَتْهَا فَانْطَلَقَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏إِلَى ‏ ‏عَلِيٍّ ‏ ‏وَفَاطِمَةَ ‏ ‏فَقَالَتْ إِنَّ ‏ ‏عَائِشَةَ ‏ ‏سَبَّتْهَا وَقَالَتْ لَكُمْ وَقَالَتْ لَكُمْ فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏لِفَاطِمَةَ ‏ ‏اذْهَبِي إِلَيْهِ فَقُولِي إِنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ لَنَا وَقَالَتْ لَنَا فَأَتَتْهُ فَذَكَرَتْ ذَلِكَ لَهُ فَقَالَ لَهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهَا حِبَّةُ أَبِيكِ وَرَبِّ ‏ ‏الْكَعْبَةِ ‏ ‏فَرَجَعَتْ إِلَى ‏ ‏عَلِيٍّ ‏ ‏فَذَكَرَتْ لَهُ الَّذِي قَالَ لَهَا فَقَالَ أَمَا كَفَاكَ إِلَّا أَنْ قَالَتْ لَنَا ‏ ‏عَائِشَةُ ‏ ‏وَقَالَتْ لَنَا حَتَّى أَتَتْكَ ‏ ‏فَاطِمَةُ ‏ ‏فَقُلْتَ لَهَا إِنَّهَا حِبَّةُ أَبِيكِ وَرَبِّ ‏ ‏الْكَعْبَةِ ‏ ‏حَدَّثَنَا ‏ ‏أَزْهَرُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏قَالَ أَنْبَأَنِي ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أُمِّ مُحَمَّدٍ امْرَأَةِ أَبِيهِ ‏ ‏قَالَتْ ‏ ‏وَكَانَتْ ‏ ‏تَغْشَى ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَتْ عِنْدَنَا ‏ ‏زَيْنَبُ بِنْتُ جَحْشٍ ‏ ‏فَذَكَرَ نَحْوَ حَدِيثِ ‏ ‏سُلَيْمِ بْنِ أَخْضَرَ ‏ ‏إِلَّا أَنَّ ‏ ‏سُلَيْمًا ‏ ‏قَالَ ‏ ‏أُمُّ سَلَمَةَ ‏","","",""],[23839,23839,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ أُطَيِّبُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ إِحْرَامِهِ بِأَطْيَبِ مَا أَجِدُ ‏","","",""],[23840,23840,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ النَّهْشَلِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زِيَادُ بْنُ عِلَاقَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُقَبِّلُ فِي رَمَضَانَ وَهُوَ صَائِمٌ ‏","","",""],[23841,23841,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏أَشْعَثُ بْنُ سُلَيْمٍ ‏ ‏أَخْبَرَنِي أَنَّهُ سَمِعَ ‏ ‏أَبَاهُ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحِبُّ التَّيَمُّنَ فِي شَأْنِهِ كُلِّهِ فِي طُهُورِهِ ‏ ‏وَتَرَجُّلِهِ ‏ ‏وَنَعْلِهِ قَالَتْ ثُمَّ سَأَلْتُهُ ‏ ‏بِالْكُوفَةِ ‏ ‏فَقَالَ التَّيَمُّنَ بِمَا اسْتَطَاعَ ‏","","",""],[23842,23842,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏حَدَّثَتْهُ ‏ ‏أَنَّهَا كَانَتْ ‏ ‏تَغْتَسِلُ هِيَ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ يَغْرِفُ قَبْلَهَا وَتَغْرِفُ قَبْلَهُ ‏","","",""],[23843,23843,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَهْدِيُّ بْنُ مَيْمُونٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عُثْمَانَ الْأَنْصَارِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْقَاسِمَ بْنَ مُحَمَّدِ بْنِ أَبِي بَكْرٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا سَمِعَتْهُ يَقُولُ ‏ ‏كُلُّ مُسْكِرٍ حَرَامٌ وَمَا أَسْكَرَ ‏ ‏الْفَرْقُ ‏ ‏فَمِلْءُ الْكَفِّ مِنْهُ حَرَامٌ ‏","","",""],[23844,23844,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْقَاسِمُ بْنُ الْفَضْلِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَلِيٍّ ‏ ‏قَالَ ‏ ‏كَانَتْ ‏ ‏عَائِشَةُ ‏ ‏تَدَّانُ فَقِيلَ لَهَا مَا لَكِ وَلِلدَّيْنِ قَالَتْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ عَبْدٍ كَانَتْ لَهُ نِيَّةٌ فِي أَدَاءِ دَيْنِهِ إِلَّا كَانَ لَهُ مِنْ اللَّهِ عَزَّ وَجَلَّ عَوْنٌ فَأَنَا أَلْتَمِسُ ذَلِكَ الْعَوْنَ ‏","","",""],[23845,23845,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا فَرَغَ مِنْ الْأَحْزَابِ دَخَلَ الْمُغْتَسَلَ لِيَغْتَسِلَ فَجَاءَ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَقَالَ أَوَقَدْ وَضَعْتُمْ السِّلَاحَ مَا وَضَعْنَا أَسْلِحَتَنَا بَعْدُ انْهَدْ إِلَى ‏ ‏بَنِي قُرَيْظَةَ ‏ ‏فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏كَأَنِّي أَنْظُرُ إِلَى ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏مِنْ ‏ ‏خَلَلِ ‏ ‏الْبَابِ قَدْ ‏ ‏عَصَبَ ‏ ‏رَأْسَهُ مِنْ الْغُبَارِ ‏","","",""],[23846,23846,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَرْقِي رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏الْعَيْنِ ‏ ‏فَأَضَعُ يَدِي عَلَى صَدْرِهِ وَأَقُولُ ‏ ‏امْسَحْ ‏ ‏الْبَاسَ ‏ ‏رَبَّ النَّاسِ بِيَدِكَ الشِّفَاءُ لَا كَاشِفَ لَهُ إِلَّا أَنْتَ ‏","","",""],[23847,23847,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبَّادٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ فِي ‏ ‏رُكُوعِهِ ‏ ‏مِنْ صَلَاةِ اللَّيْلِ لَا إِلَهَ إِلَّا أَنْتَ ‏","","",""],[23848,23848,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدُ بْنُ هِلَالٍ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَأَخْرَجَتْ إِلَيْنَا ‏ ‏إِزَارًا ‏ ‏غَلِيظًا مِمَّا صُنِعَ ‏ ‏بِالْيَمَنِ ‏ ‏وَكِسَاءً مِنْ الَّتِي يَدْعُونَ ‏ ‏الْمُلَبَّدَةَ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏تَدْعُونَ ‏ ‏فَقَالَتْ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُبِضَ فِي هَذَيْنِ الثَّوْبَيْنِ ‏","","",""],[23849,23849,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏اعْتَكَفَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏امْرَأَةٌ مِنْ أَزْوَاجِهِ مُسْتَحَاضَةٌ فَكَانَتْ ‏ ‏تَرَى الصُّفْرَةَ وَالْحُمْرَةَ فَرُبَّمَا وَضَعْنَا الطَّسْتَ تَحْتَهَا وَهِيَ تُصَلِّي ‏","","",""],[23850,23850,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏قَالَ ‏ ‏إِسْمَاعِيلُ السُّدِّىُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ الْبَهِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا كُنْتُ أَقْضِي مَا يَكُونُ عَلَيَّ مِنْ رَمَضَانَ إِلَّا فِي شَعْبَانَ حَتَّى تُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[23851,23851,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏الْقَاسِمُ بْنُ الْفَضْلِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ثُمَامَةُ بْنُ حَزْنٍ الْقُشَيْرِيُّ ‏ ‏قَالَ سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيذِ فَقَالَتْ قَدِمَ وَفْدُ ‏ ‏عَبْدِ الْقَيْسِ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَهَاهُمْ أَنْ يَنْبِذُوا فِي ‏ ‏الدُّبَّاءِ ‏ ‏وَالنَّقِيرِ ‏ ‏وَالْمُقَيَّرِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَدَعَتْ ‏ ‏جَارِيَةً ‏ ‏حَبَشِيَّةً فَقَالَتْ لِي سَلْ هَذِهِ فَإِنَّهَا كَانَتْ ‏ ‏تَنْبِذُ ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏سِقَاءٍ ‏ ‏مِنْ اللَّيْلِ ‏ ‏أُوكِئُهُ وَأُعَلِّقُهُ فَإِذَا أَصْبَحَ شَرِبَ مِنْهُ ‏","","",""],[23852,23852,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أُتِيَ بِالْمَرِيضِ قَالَ ‏ ‏أَذْهِبْ ‏ ‏الْبَاسَ ‏ ‏رَبَّ النَّاسِ وَاشْفِ أَنْتَ الشَّافِي لَا شِفَاءَ إِلَّا شِفَاؤُكَ شِفَاءً لَا ‏ ‏يُغَادِرُ ‏ ‏سَقَمًا ‏","","",""],[23853,23853,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏شُمَيْسَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ فِي سَفَرٍ لَهُ ‏ ‏فَاعْتَلَّ ‏ ‏بَعِيرٌ ‏ ‏لِصَفِيَّةَ ‏ ‏وَفِي إِبِلِ ‏ ‏زَيْنَبَ ‏ ‏فَضْلٌ ‏ ‏فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ بَعِيرًا ‏ ‏لِصَفِيَّةَ ‏ ‏اعْتَلَّ ‏ ‏فَلَوْ أَعْطَيْتِهَا بَعِيرًا مِنْ إِبِلِكِ فَقَالَتْ أَنَا أُعْطِي تِلْكَ الْيَهُودِيَّةَ قَالَ فَتَرَكَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَا الْحِجَّةِ وَالْمُحَرَّمَ شَهْرَيْنِ ‏ ‏أَوْ ثَلَاثَةً ‏ ‏لَا ‏ ‏يَأْتِيهَا قَالَتْ حَتَّى يَئِسْتُ مِنْهُ وَحَوَّلْتُ سَرِيرِي قَالَتْ فَبَيْنَمَا أَنَا يَوْمًا بِنِصْفِ النَّهَارِ إِذَا أَنَا بِظِلِّ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُقْبِلٌ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنِيهِ ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏شُمَيْسَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ سَمِعْتُهُ بَعْدُ ‏ ‏يُحَدِّثُهُ عَنْ ‏ ‏شُمَيْسَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏و قَالَ ‏ ‏بَعْدُ فِي حَجٍّ ‏ ‏أَوْ عُمْرَةٍ ‏ ‏قَالَ وَلَا أَظُنُّهُ إِلَّا قَالَ فِي حَجَّةِ الْوَدَاعِ ‏","","",""],[23854,23854,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا جَعَلَتْ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بُرْدَةً سَوْدَاءَ مِنْ صُوفٍ فَذَكَرَ سَوَادَهَا وَبَيَاضَهُ ‏ ‏فَلَبِسَهَا فَلَمَّا عَرِقَ وَجَدَ رِيحَ الصُّوفِ قَذَفَهَا وَكَانَ يُحِبُّ الرِّيحَ الطَّيِّبَةَ ‏","","",""],[23855,23855,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي مُلَيْكَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْقَاسِمُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَلَا هَذِهِ الْآيَةَ ‏ { ‏هُوَ الَّذِي أَنْزَلَ عَلَيْكَ الْكِتَابَ مِنْهُ آيَاتٌ ‏ ‏مُحْكَمَاتٌ ‏ ‏هُنَّ أُمُّ الْكِتَابِ وَأُخَرُ ‏ ‏مُتَشَابِهَاتٌ ‏ ‏فَأَمَّا الَّذِينَ فِي قُلُوبِهِمْ ‏ ‏زَيْغٌ ‏ } ‏حَتَّى إِذَا فَرَغَ مِنْهَا قَالَ قَدْ سَمَّاهُمْ اللَّهُ عَزَّ وَجَلَّ فَإِذَا رَأَيْتُمُوهُمْ فَاحْذَرُوهُمْ ‏","","",""],[23856,23856,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏قَالَ لَهَا ‏ ‏فِي أَيِّ يَوْمٍ مَاتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ فِي يَوْمِ ‏ ‏الِاثْنَيْنِ فَقَالَ مَا شَاءَ اللَّهُ إِنِّي لَا أَرْجُو فِيمَا بَيْنِي وَبَيْنَ اللَّيْلِ قَالَ فَفِيمَ كَفَّنْتُمُوهُ قَالَتْ فِي ثَلَاثَةِ أَثْوَابٍ بِيضٍ ‏ ‏سُحُولِيَّةٍ ‏ ‏يَمَانِيَةٍ لَيْسَ فِيهَا قَمِيصٌ وَلَا عِمَامَةٌ وَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏انْظُرِي ثَوْبِي هَذَا فِيهِ رَدْعُ زَعْفَرَانٍ أَوْ ‏ ‏مِشْقٌ ‏ ‏فَاغْسِلِيهِ وَاجْعَلِي مَعَهُ ثَوْبَيْنِ آخَرَيْنِ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏يَا ‏ ‏أَبَتِ هُوَ ‏ ‏خَلِقٌ ‏ ‏قَالَ إِنَّ الْحَيَّ أَحَقُّ بِالْجَدِيدِ وَإِنَّمَا هُوَ ‏ ‏لِلْمُهْلَةِ ‏ ‏وَكَانَ ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي بَكْرٍ ‏ ‏أَعْطَاهُمْ ‏ ‏حُلَّةً ‏ ‏حِبَرَةً ‏ ‏فَأُدْرِجَ ‏ ‏فِيهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ اسْتَخْرَجُوهُ مِنْهَا فَكُفِّنَ فِي ثَلَاثَةِ أَثْوَابٍ بِيضٍ قَالَ فَأَخَذَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏الْحُلَّةَ فَقَالَ لَأُكَفِّنَنَّ نَفْسِي فِي شَيْءٍ مَسَّ جِلْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ بَعْدَ ذَلِكَ وَاللَّهِ لَا أُكَفِّنُ نَفْسِي فِي شَيْءٍ مَنَعَهُ اللَّهُ عَزَّ وَجَلَّ نَبِيَّهُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُكَفَّنَ فِيهِ فَمَاتَ لَيْلَةَ الثُّلَاثَاءِ وَدُفِنَ لَيْلًا وَمَاتَتْ ‏ ‏عَائِشَةُ ‏ ‏فَدَفَنَهَا ‏ ‏عَبْدُ اللَّهِ بْنُ الزُّبَيْرِ ‏ ‏لَيْلًا ‏","","",""],[23857,23857,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ شَدَّادٍ ‏ ‏عَنْ ‏ ‏أَبِي عُذْرَةَ ‏ ‏قَالَ وَكَانَ قَدْ أَدْرَكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى الرِّجَالَ وَالنِّسَاءَ عَنْ الْحَمَّامَاتِ ثُمَّ رَخَّصَ لِلرِّجَالِ أَنْ يَدْخُلُوهَا فِي الْمَآزِرِ ‏","","",""],[23858,23858,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏جَعَلْتُمُونَا بِمَنْزِلَةِ الْكَلْبِ وَالْحِمَارِ لَقَدْ ‏ ‏رَأَيْتُنِي وَأَنَا تَحْتَ كِسَائِي بَيْنَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبَيْنَ الْقِبْلَةِ فَأَكْرَهُ أَنْ أَسْنَحَ بَيْنَ يَدَيْهِ حَتَّى ‏ ‏أَنْسَلَّ ‏ ‏مِنْ تَحْتِ الْقَطِيفَةِ ‏ ‏انْسِلَالًا ‏","","",""],[23859,23859,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَفْرُكُ الْمَنِيَّ مِنْ ثَوْبِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ يَذْهَبُ فَيُصَلِّي فِيهِ ‏","","",""],[23860,23860,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُفَضَّلُ يَعْنِي ابْنَ فَضَالَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ الْهَادِ ‏ ‏أَنَّ ‏ ‏عُرْوَةَ بْنَ الزُّبَيْرِ ‏ ‏كَانَ يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا كَانَتْ ‏ ‏تَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا طَلَعَ الْفَجْرُ رَكَعَ رَكْعَتَيْنِ خَفِيفَتَيْنِ ثُمَّ اضْطَجَعَ عَلَى جَنْبِهِ الْأَيْمَنِ ‏","","",""],[23861,23861,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏حَدَّثَنَا ‏ ‏الْمُفَضَّلُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ حَرْمَلَةَ الْأَسْلَمِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ نِيارٍ الْأَسْلَمِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏أَهْدَتْ ‏ ‏أُمُّ سُنْبُلَةَ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَبَنًا فَلَمْ تَجِدْهُ فَقَالَتْ لَهَا إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ نَهَى أَنْ يُؤْكَلَ طَعَامُ ‏ ‏الْأَعْرَابِ ‏ ‏فَدَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏فَقَالَ مَا هَذَا مَعَكِ يَا ‏ ‏أُمَّ سُنْبُلَةَ ‏ ‏قَالَتْ لَبَنًا أَهْدَيْتُ لَكَ يَا رَسُولَ اللَّهِ قَالَ اسْكُبِي ‏ ‏أُمَّ سُنْبُلَةَ ‏ ‏فَسَكَبَتْ فَقَالَ نَاوِلِي ‏ ‏أَبَا بَكْرٍ ‏ ‏فَفَعَلَتْ فَقَالَ اسْكُبِي ‏ ‏أُمَّ سُنْبُلَةَ ‏ ‏فَسَكَبَتْ فَنَاوَلَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَشَرِبَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَشْرَبُ مِنْ لَبَنٍ وَأَبْرَدِهَا عَلَى الْكَبِدِ يَا رَسُولَ اللَّهِ كُنْتُ حُدِّثْتُ أَنَّكَ قَدْ نَهَيْتَ عَنْ طَعَامِ ‏ ‏الْأَعْرَابِ ‏ ‏فَقَالَ يَا ‏ ‏عَائِشَةُ ‏ ‏إِنَّهُمْ لَيْسُوا ‏ ‏بِالْأَعْرَابِ ‏ ‏هُمْ أَهْلُ بَادِيَتِنَا وَنَحْنُ أَهْلُ حَاضِرَتِهِمْ وَإِذَا دُعُوا أَجَابُوا فَلَيْسُوا ‏ ‏الْأَعْرَابِ ‏","","",""],[23862,23862,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو زُبَيْدٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏نَهَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْمُزَفَّتِ ‏","","",""],[23863,23863,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ قُرْطٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ذَهَبَ أَحَدُكُمْ إِلَى ‏ ‏الْغَائِطِ ‏ ‏فَلْيَذْهَبْ مَعَهُ بِثَلَاثَةِ أَحْجَارٍ ‏ ‏يَسْتَطِيبُ ‏ ‏بِهِنَّ فَإِنَّهُنَّ تُجْزِئُ عَنْهُ ‏","","",""],[23864,23864,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏عَنِ ‏ ‏الْمُطَّلِبِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الرَّجُلَ لَيُدْرِكُ بِحُسْنِ الْخُلُقِ دَرَجَةَ الصَّائِمِ الْقَائِمِ ‏","","",""],[23865,23865,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏فُلَيْحُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ عَجْلَانَ ‏ ‏وَمُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ عَبَّادٍ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَمَرَتْ بِجِنَازَةِ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏أَنْ تَمُرَّ عَلَيْهَا فِي الْمَسْجِدِ فَبَلَغَهَا أَنْ قِيلَ فِي ذَلِكَ فَقَالَتْ مَا أَسْرَعَ النَّاسَ إِلَى الْقَوْلِ وَاللَّهِ ‏ ‏مَا صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏سُهَيْلِ ابْنِ بَيْضَاءَ ‏ ‏إِلَّا فِي الْمَسْجِدِ ‏","","",""],[23866,23866,"","","‏ ‏حَدَّثَنَا ‏ ‏النَّضْرُ بْنُ إِسْمَاعِيلَ أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ ‏ ‏بِالْمُدِّ ‏ ‏وَيَغْتَسِلُ ‏ ‏بِالصَّاعِ ‏","","",""],[23867,23867,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏إِنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏إِزَارٍ ‏ ‏وَرِدَاءٍ ‏ ‏فَاسْتَقْبَلَ الْقِبْلَةَ وَبَسَطَ يَدَيْهِ فَقَالَ اللَّهُمَّ إِنَّمَا أَنَا بَشَرٌ فَأَيَّ عَبْدٍ مِنْ عِبَادِكَ ضَرَبْتُ أَوْ آذَيْتُ فَلَا تُعَاقِبْنِي بِهِ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏فِيهِ ‏","","",""],[23868,23868,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ الْقَاسِمِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَتْ ‏ ‏سَوْدَةُ ‏ ‏امْرَأَةً ‏ ‏ثَبِطَةً ‏ ‏ثَقِيلَةً فَاسْتَأْذَنَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏تُفِيضَ ‏ ‏مِنْ ‏ ‏جَمْعٍ ‏ ‏قَبْلَ أَنْ تَقِفَ ‏ ‏وَلَوَدِدْتُ أَنِّي كُنْتُ اسْتَأْذَنْتُهُ وَأَذِنَ لِي ‏ ‏وَكَانَ ‏ ‏الْقَاسِمُ ‏ ‏يَكْرَهُ أَنْ يُفِيضَ حَتَّى يَقِفَ ‏","","",""],[23869,23869,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنِي ‏ ‏جَعْفَرُ بْنُ كَيْسَانَ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏مُعَاذَةُ الْعَدَوِيَّةُ ‏ ‏قَالَتْ ‏ ‏دَخَلْتُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَقَالَتْ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تَفْنَى أُمَّتِي إِلَّا بِالطَّعْنِ وَالطَّاعُونِ ‏","","",""],[23870,23870,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏جَبْرُ بْنُ حَبِيبٍ ‏ ‏عَنْ ‏ ‏أُمِّ كُلْثُومٍ بِنْتِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَّمَهَا هَذَا الدُّعَاءَ ‏ ‏اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ الْخَيْرِ كُلِّهِ عَاجِلِهِ وَآجِلِهِ مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ خَيْرِ مَا سَأَلَكَ عَبْدُكَ وَنَبِيُّكَ ‏ ‏مُحَمَّدٌ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَعُوذُ بِكَ مِنْ شَرِّ مَا عَاذَ مِنْهُ عَبْدُكَ وَنَبِيُّكَ اللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ وَأَسْأَلُكَ أَنْ تَجْعَلَ كُلَّ قَضَاءٍ ‏ ‏تَقْضِيهِ لِي خَيْرًا ‏","","",""],[23871,23871,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَسْوَدُ بْنُ شَيْبَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو نَوْفَلِ بْنُ أَبِي عَقْرَبٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏هَلْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُتَسَامَعُ عِنْدَهُ الشِّعْرُ قَالَتْ كَانَ أَبْغَضَ الْحَدِيثِ إِلَيْهِ ‏","","",""],[23872,23872,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُ إِحْدَانَا إِذَا حَاضَتْ أَنْ ‏ ‏تَأْتَزِرَ ‏ ‏ثُمَّ ‏ ‏يُبَاشِرُهَا ‏","","",""],[23873,23873,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏سَعْدُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَهْوَى ‏ ‏إِلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيُقَبِّلَنِي فَقُلْتُ إِنِّي صَائِمَةٌ قَالَ وَأَنَا صَائِمٌ قَالَتْ ‏ ‏فَأَهْوَى ‏ ‏إِلَيَّ فَقَبَّلَنِي ‏","","",""],[23874,23874,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏دَوُادُ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏إِذَا بُدِّلَتْ الْأَرْضُ غَيْرَ الْأَرْضِ وَالسَّمَوَاتُ وَبَرَزُوا لِلَّهِ الْوَاحِدِ الْقَهَّارِ أَيْنَ النَّاسُ يَوْمَئِذٍ قَالَ عَلَى الصِّرَاطِ ‏","","",""],[23875,23875,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو بَكْرِ بْنُ حَفْصٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُرْوَةَ بْنَ الزُّبَيْرِ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏مَا تَقُولُونَ يَقْطَعُ الصَّلَاةَ قَالَ يَقُولُونَ يَقْطَعُ الصَّلَاةَ الْمَرْأَةُ وَالْكَلْبُ وَالْحِمَارُ قَالَتْ لَقَدْ ‏ ‏رَأَيْتُنِي مُعْتَرِضَةً بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَاعْتِرَاضِ الْجِنَازَةِ ‏","","",""],[23876,23876,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ بِقَتْلِ ‏ ‏ذِي الطُّفْيَتَيْنِ ‏ ‏فَإِنَّهُ يَلْتَمِسُ الْبَصَرَ وَيُصِيبُ ‏ ‏الْحَبَلَ ‏","","",""],[23877,23877,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏تُرْجِي مَنْ تَشَاءُ مِنْهُنَّ وَتُؤْوِي إِلَيْكَ مَنْ تَشَاءُ ‏} ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏مَا أَرَى رَبَّكَ عَزَّ وَجَلَّ إِلَّا يُسَارِعُ لَكَ فِي هَوَاكَ ‏","","",""],[23878,23878,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْأَسْوَدَ بْنَ يَزِيدَ ‏ ‏ومَسْرُوقًا ‏ ‏يَقُولَانِ ‏ ‏نَشْهَدُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ مَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدِي فِي يَوْمٍ إِلَّا ‏ ‏صَلَّى رَكْعَتَيْنِ بَعْدَ الْعَصْرِ ‏","","",""],[23879,23879,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّها قَالَتْ ‏ ‏دَخَلَ عَلَيْنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏فِي يَوْمِ عِيدٍ وَعِنْدَنَا ‏ ‏جَارِيَتَانِ تَذْكُرَانِ يَوْمَ ‏ ‏بُعَاثَ ‏ ‏يَوْمٌ قُتِلَ فِيهِ ‏ ‏صَنَادِيدُ ‏ ‏الْأَوْسِ ‏ ‏وَالْخَزْرَجِ ‏ ‏فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏عِبَادَ اللَّهِ ‏ ‏أَمَزْمُورُ ‏ ‏الشَّيْطَانِ عِبَادَ اللَّهِ ‏ ‏أَمَزْمُورُ ‏ ‏الشَّيْطَانِ قَالَهَا ثَلَاثًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏إِنَّ لِكُلِّ قَوْمٍ عِيدًا وَإِنَّ الْيَوْمَ عِيدُنَا ‏","","",""],[23880,23880,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏عَنْ ‏ ‏حُصَيْنِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْأَشْعَثِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏بَيْنَا أَنَا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ اسْتَأْذَنَ رَجُلٌ مِنْ ‏ ‏الْيَهُودِ ‏ ‏فَأَذِنَ لَهُ فَقَالَ السَّامُ عَلَيْكَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيْكَ قَالَتْ فَهَمَمْتُ أَنْ أَتَكَلَّمَ قَالَتْ ثُمَّ دَخَلَ الثَّانِيَةَ فَقَالَ مِثْلَ ذَلِكَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيْكَ قَالَتْ ثُمَّ دَخَلَ الثَّالِثَةَ فَقَالَ السَّامُ عَلَيْكَ قَالَتْ فَقُلْتُ بَلْ السَّامُ عَلَيْكُمْ وَغَضَبُ اللَّهِ إِخْوَانَ الْقِرَدَةِ وَالْخَنَازِيرِ أَتُحَيُّونَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَا لَمْ يُحَيِّهِ بِهِ اللَّهُ قَالَتْ فَنَظَرَ إِلَيَّ فَقَالَ مَهْ ‏ ‏إِنَّ اللَّهَ لَا يُحِبُّ ‏ ‏الْفُحْشَ ‏ ‏وَلَا التَّفَحُّشَ قَالُوا قَوْلًا فَرَدَدْنَاهُ عَلَيْهِمْ فَلَمْ يَضُرَّنَا شَيْءٌ وَلَزِمَهُمْ إِلَى يَوْمِ الْقِيَامَةِ إِنَّهُمْ لَا يَحْسُدُونَا عَلَى شَيْءٍ كَمَا يَحْسُدُونَا عَلَى يَوْمِ الْجُمُعَةِ الَّتِي هَدَانَا اللَّهُ لَهَا وَضَلُّوا عَنْهَا وَعَلَى الْقِبْلَةِ الَّتِي هَدَانَا اللَّهُ لَهَا وَضَلُّوا عَنْهَا وَعَلَى قَوْلِنَا خَلْفَ الْإِمَامِ آمِينَ ‏","","",""],[23881,23881,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَنْصُورُ بْنُ عَبْدِ الرَّحْمَنِ الْحَجَبِيُّ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏صَفِيَّةَ بِنْتِ شَيْبَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَّكِئُ عَلَيَّ وَأَنَا حَائِضٌ فَيَقْرَأُ الْقُرْآنَ ‏","","",""],[23882,23882,"","","‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَتَتْنِي ‏ ‏بَرِيرَةُ ‏ ‏تَسْتَعِينُنِي فِي مُكَاتَبَتِهَا فَقُلْتُ لَهَا إِنْ شَاءَ مَوَالِيكِ ‏ ‏صَبَبْتُ ‏ ‏لَهُمْ ثَمَنَكِ ‏ ‏صَبَّةً ‏ ‏وَاحِدَةً وَأَعْتَقْتُكِ فَاسْتَأْمَرَتْ مَوَالِيَهَا فَقَالُوا لَا إِلَّا أَنْ تَشْتَرِطَ لَنَا الْوَلَاءَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اشْتَرِيهَا فَإِنَّمَا الْوَلَاءُ لِمَنْ أَعْتَقَ ‏","","",""],[23883,23883,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أُمِّ بَكْرٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ ‏ ‏بَاعَ أَرْضًا لَهُ مِنْ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏بِأَرْبَعِينَ أَلْفَ دِينَارٍ فَقَسَمَهُ فِي فُقَرَاءِ ‏ ‏بَنِي زُهْرَةَ ‏ ‏وَفِي ذِي الْحَاجَةِ مِنْ النَّاسِ وَفِي ‏ ‏أُمَّهَاتِ الْمُؤْمِنِينَ قَالَ ‏ ‏الْمِسْوَرُ ‏ ‏فَدَخَلْتُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏بِنَصِيبِهَا مِنْ ذَلِكَ فَقَالَتْ مَنْ أَرْسَلَ بِهَذَا قُلْتُ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏فَقَالَتْ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَحِنُّ عَلَيْكُمْ بَعْدِي إِلَّا الصَّابِرُونَ سَقَى اللَّهُ ‏ ‏ابْنَ عَوْفٍ ‏ ‏مِنْ سَلْسَبِيلِ الْجَنَّةِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏حَدَّثَتْنَا ‏ ‏أُمُّ بَكْرٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ ‏ ‏بَاعَ أَرْضًا لَهُ فَذَكَرَ الْحَدِيثَ إِلَّا أَنَّهُ قَالَ قَالَتْ أَمَا إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ لَا ‏ ‏يَحْنَا عَلَيْكُمْ بَعْدِي إِلَّا الصَّابِرُونَ ‏","","",""],[23884,23884,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْأَشْجَعِيِّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَقَدْ ‏ ‏رَأَيْتُنِي ‏ ‏أَحُتُّ ‏ ‏الْمَنِيَّ مِنْ ثَوْبِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ أَفْرُكُهُ ‏","","",""],[23885,23885,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنَامُ حَتَّى يَنْفُخَ ثُمَّ يَقُومُ فَيُصَلِّي وَلَا يَتَوَضَّأُ ‏","","",""],[23886,23886,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدِ بْنِ جُدْعَانَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَاوَزَ ‏ ‏الْخِتَانُ ‏ ‏الْخِتَانَ ‏ ‏فَقَدْ وَجَبَ الْغُسْلُ ‏","","",""],[23887,23887,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا رَأَيْتُ أَحَدًا كَانَ أَشَدَّ تَعْجِيلًا لِلظُّهْرِ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا ‏ ‏أَبِي بَكْرٍ ‏ ‏وَلَا ‏ ‏عُمَرَ ‏","","",""],[23888,23888,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مُغِيرَةُ بْنُ زِيَادٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُؤَخِّرُ الظُّهْرَ وَيُعَجِّلُ الْعَصْرَ وَيُؤَخِّرُ الْمَغْرِبَ وَيُعَجِّلُ الْعِشَاءَ فِي السَّفَرِ ‏","","",""],[23889,23889,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِمْرَانَ الْحَجَبِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏صَفِيَّةَ بِنْتَ شَيْبَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَحَلَّ ‏ ‏اسْمِي وَحَرَّمَ كُنْيَتِي وَمَا حَرَّمَ كُنْيَتِي وَأَحَلَّ اسْمِي ‏","","",""],[23890,23890,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْعُمَرِيُّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏وَعَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُلْحِدَ ‏ ‏لَهُ ‏ ‏لَحْدٌ ‏","","",""],[23891,23891,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ مَوْتِ الْفَجْأَةِ فَقَالَ ‏ ‏رَاحَةٌ لِلْمُؤْمِنِ وَأَخْذَةُ أَسَفٍ لِفَاجِرٍ ‏","","",""],[23892,23892,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏كَهْمَسٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏جَاءَتْ فَتَاةٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّ أَبِي زَوَّجَنِي ابْنَ أَخِيهِ يَرْفَعُ بِي ‏ ‏خَسِيسَتَهُ ‏ ‏فَجَعَلَ الْأَمْرَ إِلَيْهَا قَالَتْ فَإِنِّي قَدْ أَجَزْتُ مَا صَنَعَ أَبِي وَلَكِنْ أَرَدْتُ أَنْ تَعْلَمَ النِّسَاءُ أَنْ لَيْسَ لِلْآبَاءِ مِنْ الْأَمْرِ شَيْءٌ ‏","","",""],[23893,23893,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏وَأَنْذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ ‏} ‏قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا ‏ ‏فَاطِمَةُ بِنْتَ مُحَمَّدٍ ‏ ‏يَا ‏ ‏صَفِيَّةُ بِنْتَ عَبْدِ الْمُطَّلِبِ ‏ ‏يَا ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏لَا أَمْلِكُ لَكُمْ مِنْ اللَّهِ شَيْئًا سَلُونِي مِنْ مَالِي مَا شِئْتُمْ ‏","","",""],[23894,23894,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَنْ حَدَّثَكَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَالَ قَائِمًا فَلَا تُصَدِّقْهُ ‏ ‏مَا بَالَ رَسُولُ اللَّهِ قَائِمًا مُنْذُ أُنْزِلَ عَلَيْهِ الْقُرْآنُ ‏","","",""],[23895,23895,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَوْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَحَّى بِكَبْشَيْنِ سَمِينَيْنِ عَظِيمَيْنِ ‏ ‏أَمْلَحَيْنِ ‏ ‏أَقْرَنَيْنِ ‏ ‏مُوجَأَيْنِ ‏","","",""],[23896,23896,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زِيَادِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَابِسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏إِنْ ‏ ‏كُنَّا لَنَرْفَعُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْكُرَاعَ ‏ ‏فَيَأْكُلُهُ بَعْدَ شَهْرٍ ‏","","",""],[23897,23897,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَبْدِ الْمَلِكِ بْنِ أَبِي الصَّغِيرَاءِ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ كَانَ عِنْدَنَا سَعَةٌ لَهَدَمْتُ ‏ ‏الْكَعْبَةَ ‏ ‏وَلَبَنَيْتُهَا ‏ ‏وَلَجَعَلْتُ لَهَا بَابَيْنِ بَابًا يَدْخُلُ النَّاسُ مِنْهُ وَبَابًا يَخْرُجُونَ مِنْهُ ‏ ‏قَالَتْ ‏ ‏فَلَمَّا ‏ ‏وَلِيَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏هَدَمَهَا فَجَعَلَ لَهَا بَابَيْنِ قَالَتْ فَكَانَتْ كَذَلِكَ فَلَمَّا ظَهَرَ ‏ ‏الْحَجَّاجُ ‏ ‏عَلَيْهِ هَدَمَهَا وَأَعَادَ بِنَاءَهَا الْأَوَّلَ ‏","","",""],[23898,23898,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ الْأَقْمَرِ ‏ ‏عَنْ ‏ ‏أَبِي حُذَيْفَةَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏حَكَتْ امْرَأَةً عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَكَرَتْ قِصَرَهَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏اغْتَبْتِيهَا ‏","","",""],[23899,23899,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ الْأَقْمَرِ ‏ ‏عَنْ ‏ ‏أَبِي حُذَيْفَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا حَكَتْ امْرَأَةً فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أُحِبُّ أَنِّي حَكَيْتُ أَحَدًا وَأَنَّ لِي كَذَا وَكَذَا ‏","","",""],[23900,23900,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏حَبِيبٍ يَعْنِي ابْنَ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سُرِقَ لِي ثَوْبٌ فَجَعَلْتُ أَدْعُو عَلَيْهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تُسَبِّخِي ‏ ‏عَنْهُ ‏","","",""],[23901,23901,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏مَرَّةً أُخْرَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهُ سُرِقَ ثَوْبٌ لَهَا فَدَعَتْ عَلَى صَاحِبِهَا فَقَالَ لَا تُسَبِّخِي عَنْهُ ‏","","",""],[23902,23902,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ أَبِي النُّجُودِ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا تَرَكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دِينَارًا وَلَا ‏ ‏دِرْهَمًا وَلَا عَبْدًا وَلَا أَمَةً وَلَا شَاةً وَلَا بَعِيرًا ‏","","",""],[23903,23903,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ الْأَصْبَهَانِيِّ ‏ ‏عَنْ ‏ ‏مُجَاهِدِ بْنِ وَرْدَانَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏مَوْلًى ‏ ‏لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَعَ مِنْ نَخْلَةٍ فَمَاتَ وَتَرَكَ شَيْئًا وَلَمْ يَدَعْ وَلَدًا وَلَا ‏ ‏حَمِيمًا ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْطُوا مِيرَاثَهُ رَجُلًا مِنْ أَهْلِ قَرْيَتِهِ ‏","","",""],[23904,23904,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْحَائِضُ تَقْضِي الْمَنَاسِكَ كُلَّهَا إِلَّا الطَّوَافَ ‏ ‏بِالْبَيْتِ ‏","","",""],[23905,23905,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏خَرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ عِنْدِي وَهُوَ قَرِيرُ الْعَيْنِ طَيِّبُ النَّفْسِ ثُمَّ رَجَعَ إِلَيَّ وَهُوَ حَزِينٌ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّكَ خَرَجْتَ مِنْ عِنْدِي وَأَنْتَ قَرِيرُ الْعَيْنِ طَيِّبُ النَّفْسِ وَرَجَعْتَ وَأَنْتَ حَزِينٌ فَقَالَ ‏ ‏إِنِّي دَخَلْتُ ‏ ‏الْكَعْبَةَ ‏ ‏وَوَدِدْتُ أَنِّي لَمْ أَكُنْ فَعَلْتُ إِنِّي أَخَافُ أَنْ أَكُونَ أَتْعَبْتُ أُمَّتِي مِنْ بَعْدِي ‏","","",""],[23906,23906,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سُلَيْمٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اتَّقُوا النَّارَ وَلَوْ ‏ ‏بِشِقِّ ‏ ‏تَمْرَةٍ ‏","","",""],[23907,23907,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْقَاسِمُ بْنُ الْفَضْلِ ‏ ‏حَدَّثَنِي ‏ ‏ثُمَامَةُ بْنُ حَزْنٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ ‏ ‏النَّبِيذِ ‏ ‏فَقَالَتْ هَذِهِ خَادِمُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَلْهَا الْجَارِيَةُ حَبَشِيَّةٌ فَقَالَتْ ‏ ‏كُنْتُ أَنْبِذُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏سِقَاءٍ ‏ ‏عِشَاءً ‏ ‏فَأُوكِئُهُ ‏ ‏فَإِذَا أَصْبَحَ شَرِبَ مِنْهُ ‏","","",""],[23908,23908,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تُصَلِّي ‏ ‏الْمُسْتَحَاضَةُ ‏ ‏وَإِنْ قَطَرَ الدَّمُ عَلَى الْحَصِيرِ ‏","","",""],[23909,23909,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ أَبِي زَائِدَةَ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ شَيْبَةَ ‏ ‏عَنْ ‏ ‏طَلْقِ بْنِ حَبِيبٍ ‏ ‏عَنِ ‏ ‏ابْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَشْرٌ مِنْ الْفِطْرَةِ قَصُّ الشَّارِبِ وَإِعْفَاءُ اللِّحْيَةِ وَالسِّوَاكُ وَاسْتِنْشَاقٌ بِالْمَاءِ وَقَصُّ الْأَظْفَارِ وَغَسْلُ ‏ ‏الْبَرَاجِمِ ‏ ‏وَنَتْفُ الْإِبْطِ وَحَلْقُ ‏ ‏الْعَانَةِ ‏ ‏وَانْتِقَاصُ الْمَاءِ ‏ ‏يَعْنِي ‏ ‏الِاسْتِنْجَاءَ ‏ ‏قَالَ ‏ ‏زَكَرِيَّا ‏ ‏قَالَ ‏ ‏مُصْعَبٌ ‏ ‏وَنَسِيتُ الْعَاشِرَةَ إِلَّا أَنْ تَكُونَ الْمَضْمَضَةَ ‏","","",""],[23910,23910,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏وَسُفْيَانُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا كُنْتُ أَلْقَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏السَّحَرِ ‏ ‏إِلَّا وَهُوَ عِنْدِي نَائِمًا ‏","","",""],[23911,23911,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ سُوَيْدٍ الثَّقَفِيُّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ بِنْتِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏كُنَّ أَزْوَاجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْرُجْنَ مَعَهُ عَلَيْهِنَّ ‏ ‏الضِّمَادُ ‏ ‏يَغْتَسِلْنَ فِيهِ وَيَعْرَقْنَ لَا يَنْهَاهُنَّ عَنْهُ مُحِلَّاتٍ وَلَا مُحْرِمَاتٍ ‏","","",""],[23912,23912,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ أَبِي الصَّلْتِ ‏ ‏عَنْ ‏ ‏عِرَاكٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ فَعَلُوهَا اسْتَقْبَلُوا بِمَقْعَدَتِي الْقِبْلَةَ ‏","","",""],[23913,23913,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏طَلْحَةُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏سَمِعَهُ مِنْهُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى وَعَلَيْهِ ‏ ‏مِرْطٌ ‏ ‏بَعْضُهُ عَلَيْهَا وَهِيَ حَائِضٌ ‏","","",""],[23914,23914,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَأَى ‏ ‏نَاشِئًا ‏ ‏احْمَرَّ وَجْهُهُ فَإِذَا ‏ ‏مَطَرَتْ قَالَ اللَّهُمَّ صَيِّبًا هَنِيئًا ‏","","",""],[23915,23915,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أَيْمَنُ بْنُ نَابِلٍ ‏ ‏عَنِ ‏ ‏امْرَأَةٍ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏يُقَالُ لَهَا ‏ ‏أُمُّ كُلْثُومٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْكُمْ بِالْبَغِيضِ النَّافِعِ ‏ ‏التَّلْبِينِ ‏ ‏يَعْنِي الْحَسْوَ ‏ ‏قَالَتْ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اشْتَكَى أَحَدٌ مِنْ أَهْلِهِ لَمْ تَزَلْ ‏ ‏الْبُرْمَةُ ‏ ‏عَلَى النَّارِ حَتَّى يَلْقَى أَحَدَ طَرَفَيْهِ ‏ ‏يَعْنِي يَبْرَأَ أَوْ يَمُوتَ ‏","","",""],[23916,23916,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو عُقَيْلٍ ‏ ‏عَنْ ‏ ‏بُهَيَّةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْكُمْ بِالْحَبَّةِ السَّوْدَاءِ فَإِنَّ فِيهَا شِفَاءً مِنْ كُلِّ دَاءٍ إِلَّا السَّامَ ‏ ‏يَعْنِي الْمَوْتَ ‏ ‏وَالْحَبَّةُ السَّوْدَاءُ ‏ ‏الشُّونِيزُ ‏","","",""],[23917,23917,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏وَمِسْعَرٌ ‏ ‏عَنْ ‏ ‏مَعْبَدِ بْنِ خَالِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَهَا أَنْ ‏ ‏تَسْتَرْقِيَ ‏ ‏مِنْ الْعَيْنِ ‏","","",""],[23918,23918,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏سَمِعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلًا يَقْرَأُ آيَةً فَقَالَ ‏ ‏رَحِمَهُ اللَّهُ لَقَدْ ذَكَّرَنِي آيَةً كُنْتُ أُنْسِيتُهَا ‏","","",""],[23919,23919,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏بُرْدٍ ‏ ‏عَنْ ‏ ‏عُبَادَةَ بْنِ نُسَيٍّ ‏ ‏عَنْ ‏ ‏غُضَيْفِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رُبَّمَا ‏ ‏أَوْتَرَ ‏ ‏قَبْلَ أَنْ يَنَامَ وَرُبَّمَا أَوْتَرَ بَعْدَ أَنْ يَنَامَ وَرُبَّمَا اغْتَسَلَ قَبْلَ أَنْ يَنَامَ وَرُبَّمَا نَامَ قَبْلَ أَنْ يَغْتَسِلَ مِنْ الْجَنَابَةِ ‏","","",""],[23920,23920,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ شُرَيْحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ لَهَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْوِي شَيْئًا مِنْ الشِّعْرِ قَالَتْ نَعَمْ شِعْرَ ‏ ‏عَبْدِ اللَّهِ بْنِ رَوَاحَةَ ‏ ‏كَانَ ‏ ‏يَرْوِي هَذَا الْبَيْتَ ‏ ‏وَيَأْتِيكَ بِالْأَخْبَارِ مَنْ لَمْ ‏ ‏تُزَوِّدِ ‏","","",""],[23921,23921,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏عَلِيٍّ يَعْنِي ابْنَ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي الرَّكْعَتَيْنِ بَيْنَ الْأَذَانِ وَالْإِقَامَةِ ‏","","",""],[23922,23922,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَشْعَثَ بْنِ أَبِي الشَّعْثَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا الرَّضَاعَةُ مِنْ الْمَجَاعَةِ ‏","","",""],[23923,23923,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏شِمْرٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ وَثَّابٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا ‏ ‏رَكِبَتْ جَمَلًا فَلَعَنَتْهُ فَقَالَ لَهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَرْكَبِيهِ ‏","","",""],[23924,23924,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَكَّ ‏ ‏بُزَاقًا ‏ ‏فِي الْمَسْجِدِ ‏","","",""],[23925,23925,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ إِسْحَاقَ بنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّهُ لَيُهَوِّنُ عَلَيَّ أَنِّي رَأَيْتُ بَيَاضَ كَفِّ ‏ ‏عَائِشَةَ ‏ ‏فِي الْجَنَّةِ ‏","","",""],[23926,23926,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أُسَامَةَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ كَلَامُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصْلًا يَفْقَهُهُ كُلُّ أَحَدٍ لَمْ يَكُنْ يَسْرُدُهُ سَرْدًا ‏","","",""],[23927,23927,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏أَبَانَ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏أُمِّ حَكِيمٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏صَلَّيْتُ صَلَاةً كُنْتُ ‏ ‏أُصَلِّيهَا عَلَى عَهْدِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ أَنَّ أَبِي ‏ ‏نُشِرَ ‏ ‏فَنَهَانِي عَنْهَا مَا تَرَكْتُهَا ‏","","",""],[23928,23928,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْجَبَّارِ بْنُ الْوَرْدِ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَ ‏ ‏ذُكِرَ لَهَا أَنَّ الْمَيِّتَ يُعَذَّبُ بِبُكَاءِ الْحَيِّ فَقَالَتْ إِنَّمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي رَجُلٍ كَافِرٍ ‏ ‏إِنَّهُ لَيُعَذَّبُ وَأَهْلُهُ يَبْكُونَ عَلَيْهِ ‏","","",""],[23929,23929,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي زِيَادٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا جُعِلَ الطَّوَافُ وَالسَّعْيُ بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏وَرَمْيُ ‏ ‏الْجِمَارِ ‏ ‏لِإِقَامَةِ ذِكْرِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[23930,23930,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ يَعْنِي ابْنَ شَرِيكٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏تُوعِي ‏ ‏فَيُوعِيَ ‏ ‏اللَّهُ عَلَيْكِ ‏ ‏و قَالَ ‏ ‏أُسَامَةُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏","","",""],[23931,23931,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنِ ‏ ‏الْعَبَّاسِ بْنِ ذَرِيحٍ ‏ ‏عَنِ ‏ ‏الْبَهِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏أُسَامَةَ ‏ ‏عَثَرَ بِعَتَبَةِ الْبَابِ ‏ ‏فَدَمِيَ ‏ ‏قَالَ فَجَعَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمُصُّهُ وَيَقُولُ ‏ ‏لَوْ كَانَ ‏ ‏أُسَامَةُ ‏ ‏جَارِيَةً ‏ ‏لَحَلَّيْتُهَا ‏ ‏وَلَكَسَوْتُهَا حَتَّى أُنْفِقَهَا ‏","","",""],[23932,23932,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏كَهْمَسٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ صَوْمِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ ‏ ‏مَا عَلِمْتُهُ صَامَ شَهْرًا حَتَّى يُفْطِرَ مِنْهُ وَلَا أَفْطَرَ حَتَّى يَصُومَ مِنْهُ حَتَّى مَضَى لِسَبِيلِهِ ‏","","",""],[23933,23933,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏فَرْوَةَ بْنِ نَوْفَلٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ فِي دُعَائِهِ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا عَمِلْتُ وَمِنْ شَرِّ مَا لَمْ أَعْمَلْ ‏","","",""],[23934,23934,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادٍ ‏ ‏عَنْ ‏ ‏أَبِي عُذْرَةَ ‏ ‏رَجُلٌ كَانَ أَدْرَكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْحَمَّامَاتِ لِلرِّجَالِ وَالنِّسَاءِ ثُمَّ رَخَّصَ لِلرِّجَالِ فِي ‏ ‏الْمَآزِرِ ‏ ‏وَلَمْ يُرَخِّصْ لِلنِّسَاءِ ‏","","",""],[23935,23935,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏إِنَّمَا هِيَ ‏ ‏سُهَيْلَةُ بِنْتُ سَهْلٍ ‏ ‏وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَهَا بِالْغُسْلِ لِكُلِّ صَلَاةٍ فَلَمَّا ‏ ‏شَقَّ ‏ ‏ذَلِكَ عَلَيْهَا أَمَرَهَا أَنْ تَجْمَعَ الظُّهْرَ وَالْعَصْرَ بِغُسْلٍ وَاحِدٍ وَبَيْنَ الْمَغْرِبِ وَالْعِشَاءِ بِغُسْلٍ وَاحِدٍ وَأَنْ تَغْتَسِلَ لِلصُّبْحِ ‏","","",""],[23936,23936,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يُمْنَعَ نَقْعُ الْبِئْرِ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏يَعْنِي فَضْلَ الْمَاءِ ‏","","",""],[23937,23937,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عَبَّادِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا أَنَا عِنْدَهَا إِذْ مَرَّ رَجُلٌ قَدْ ضُرِبَ فِي خَمْرٍ عَلَى بَابِهَا فَسَمِعَتْ حِسَّ النَّاسِ فَقَالَتْ أَيُّ شَيْءٍ هَذَا قُلْتُ رَجُلٌ أُخِذَ سَكْرَانًا مِنْ خَمْرٍ فَضُرِبَ فَقَالَتْ سُبْحَانَ اللَّهِ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَشْرَبُ الشَّارِبُ حِينَ يَشْرَبُ وَهُوَ مُؤْمِنٌ ‏ ‏يَعْنِي الْخَمْرَ ‏ ‏وَلَا يَزْنِي الزَّانِي حِينَ يَزْنِي وَهُوَ مُؤْمِنٌ وَلَا يَسْرِقُ السَّارِقُ حِينَ يَسْرِقُ وَهُوَ مُؤْمِنٌ وَلَا يَنْتَهِبُ مُنْتَهِبٌ نُهْبَةً ذَاتَ شَرَفٍ يَرْفَعُ النَّاسُ إِلَيْهِ فِيهَا رُءُوسَهُمْ وَهُوَ مُؤْمِنٌ فَإِيَّاكُمْ وَإِيَّاكُمْ ‏","","",""],[23938,23938,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏جَاءَتْ يَهُودِيَّةٌ فَاسْتَطْعَمَتْ عَلَى بَابِي فَقَالَتْ أَطْعِمُونِي أَعَاذَكُمْ اللَّهُ مِنْ فِتْنَةِ ‏ ‏الدَّجَّالِ ‏ ‏وَمِنْ فِتْنَةِ عَذَابِ الْقَبْرِ قَالَتْ فَلَمْ أَزَلْ أَحْبِسُهَا حَتَّى جَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ مَا تَقُولُ هَذِهِ الْيَهُودِيَّةُ قَالَ وَمَا تَقُولُ قُلْتُ تَقُولُ أَعَاذَكُمْ اللَّهُ مِنْ فِتْنَةِ ‏ ‏الدَّجَّالِ ‏ ‏وَمِنْ فِتْنَةِ عَذَابِ الْقَبْرِ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَفَعَ يَدَيْهِ ‏ ‏مَدًّا ‏ ‏يَسْتَعِيذُ بِاللَّهِ مِنْ فِتْنَةِ ‏ ‏الدَّجَّالِ ‏ ‏وَمِنْ فِتْنَةِ عَذَابِ الْقَبْرِ ثُمَّ قَالَ أَمَّا فِتْنَةُ ‏ ‏الدَّجَّالِ ‏ ‏فَإِنَّهُ لَمْ يَكُنْ نَبِيٌّ إِلَّا قَدْ حَذَّرَ أُمَّتَهُ وَسَأُحَذِّرُكُمُوهُ تَحْذِيرًا لَمْ يُحَذِّرْهُ نَبِيٌّ أُمَّتَهُ إِنَّهُ أَعْوَرُ وَاللَّهُ عَزَّ وَجَلَّ لَيْسَ بِأَعْوَرَ مَكْتُوبٌ بَيْنَ عَيْنَيْهِ كَافِرٌ يَقْرَؤُهُ كُلُّ مُؤْمِنٍ فَأَمَّا فِتْنَةُ الْقَبْرِ فَبِي تُفْتَنُونَ وَعَنِّي تُسْأَلُونَ فَإِذَا كَانَ الرَّجُلُ الصَّالِحُ أُجْلِسَ فِي قَبْرِهِ غَيْرَ فَزِعٍ وَلَا مَشْعُوفٍ ثُمَّ يُقَالُ لَهُ فِيمَ كُنْتَ فَيَقُولُ فِي الْإِسْلَامِ فَيُقَالُ مَا هَذَا الرَّجُلُ الَّذِي كَانَ فِيكُمْ فَيَقُولُ ‏ ‏مُحَمَّدٌ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَنَا بِالْبَيِّنَاتِ مِنْ عِنْدِ اللَّهِ عَزَّ وَجَلَّ فَصَدَّقْنَاهُ فَيُفْرَجُ لَهُ فُرْجَةٌ قِبَلَ النَّارِ فَيَنْظُرُ إِلَيْهَا يَحْطِمُ بَعْضُهَا بَعْضًا فَيُقَالُ لَهُ انْظُرْ إِلَى مَا وَقَاكَ اللَّهُ عَزَّ وَجَلَّ ثُمَّ يُفْرَجُ لَهُ فُرْجَةٌ إِلَى الْجَنَّةِ فَيَنْظُرُ إِلَى زَهْرَتِهَا وَمَا فِيهَا فَيُقَالُ لَهُ هَذَا مَقْعَدُكَ مِنْهَا وَيُقَالُ عَلَى الْيَقِينِ كُنْتَ وَعَلَيْهِ مِتَّ وَعَلَيْهِ تُبْعَثُ إِنْ شَاءَ اللَّهُ وَإِذَا كَانَ الرَّجُلُ السَّوْءُ أُجْلِسَ فِي قَبْرِهِ فَزِعًا مَشْعُوفًا فَيُقَالُ لَهُ فِيمَ كُنْتَ فَيَقُولُ لَا أَدْرِي فَيُقَالُ مَا هَذَا الرَّجُلُ الَّذِي كَانَ فِيكُمْ فَيَقُولُ سَمِعْتُ النَّاسَ يَقُولُونَ قَوْلًا فَقُلْتُ كَمَا قَالُوا فَتُفْرَجُ لَهُ فُرْجَةٌ قِبَلَ الْجَنَّةِ فَيَنْظُرُ إِلَى زَهْرَتِهَا وَمَا فِيهَا فَيُقَالُ لَهُ انْظُرْ إِلَى مَا صَرَفَ اللَّهُ عَزَّ وَجَلَّ عَنْكَ ثُمَّ يُفْرَجُ لَهُ فُرْجَةٌ قِبَلَ النَّارِ فَيَنْظُرُ إِلَيْهَا يَحْطِمُ بَعْضُهَا بَعْضًا وَيُقَالُ لَهُ هَذَا مَقْعَدُكَ مِنْهَا كُنْتَ عَلَى الشَّكِّ وَعَلَيْهِ مِتَّ وَعَلَيْهِ تُبْعَثُ إِنْ شَاءَ اللَّهُ ثُمَّ يُعَذَّبُ ‏ ‏قَالَ ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏فَحَدَّثَنِي ‏ ‏سَعِيدُ بْنُ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْمَيِّتَ تَحْضُرُهُ الْمَلَائِكَةُ فَإِذَا كَانَ الرَّجُلُ الصَّالِحُ قَالُوا اخْرُجِي أَيَّتُهَا النَّفْسُ الطَّيِّبَةُ كَانَتْ فِي الْجَسَدِ الطَّيِّبِ وَاخْرُجِي حَمِيدَةً وَأَبْشِرِي بِرَوْحٍ وَرَيْحَانٍ وَرَبٍّ غَيْرِ غَضْبَانَ فَلَا يَزَالُ يُقَالُ لَهَا ذَلِكَ حَتَّى تَخْرُجَ ثُمَّ يُعْرَجُ بِهَا إِلَى السَّمَاءِ فَيُسْتَفْتَحُ لَهُ فَيُقَالُ مَنْ هَذَا فَيُقَالُ فُلَانٌ فَيُقَالُ مَرْحَبًا بِالنَّفْسِ الطَّيِّبَةِ كَانَتْ فِي الْجَسَدِ الطَّيِّبِ ادْخُلِي حَمِيدَةً وَأَبْشِرِي وَيُقَالُ بِرَوْحٍ وَرَيْحَانٍ وَرَبٍّ غَيْرِ غَضْبَانَ فَلَا يَزَالُ يُقَالُ لَهَا ذَلِكَ حَتَّى ‏ ‏يُنْتَهَى بِهَا إِلَى السَّمَاءِ الَّتِي فِيهَا اللَّهُ عَزَّ وَجَلَّ فَإِذَا كَانَ الرَّجُلُ السَّوْءُ قَالُوا اخْرُجِي أَيَّتُهَا النَّفْسُ الْخَبِيثَةُ كَانَتْ فِي الْجَسَدِ الْخَبِيثِ اخْرُجِي مِنْهُ ذَمِيمَةً وَأَبْشِرِي بِحَمِيمٍ وَغَسَّاقٍ ‏ { ‏وَآخَرُ مِنْ شَكْلِهِ أَزْوَاجٌ ‏} ‏فَمَا يَزَالُ يُقَالُ لَهَا ذَلِكَ حَتَّى تَخْرُجَ ثُمَّ يُعْرَجُ بِهَا إِلَى السَّمَاءِ فَيُسْتَفْتَحُ لَهَا فَيُقَالُ مَنْ هَذَا فَيُقَالُ فُلَانٌ فَيُقَالُ لَا مَرْحَبًا بِالنَّفْسِ الْخَبِيثَةِ كَانَتْ فِي الْجَسَدِ الْخَبِيثِ ارْجِعِي ذَمِيمَةً فَإِنَّهُ لَا يُفْتَحُ لَكِ أَبْوَابُ السَّمَاءِ فَتُرْسَلُ مِنْ السَّمَاءِ ثُمَّ تَصِيرُ إِلَى الْقَبْرِ فَيُجْلَسُ الرَّجُلُ الصَّالِحُ فَيُقَالُ لَهُ وَيَرُدُّ مِثْلَ مَا فِي حَدِيثِ ‏ ‏عَائِشَةَ ‏ ‏سَوَاءً ‏","","",""],[23939,23939,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏دِقْرَةُ أُمُّ عَبْدِ الرَّحْمَنِ بْنِ أُذَيْنَةَ ‏ ‏قَالَتْ ‏ ‏كُنَّا نَطُوفُ ‏ ‏بِالْبَيْتِ ‏ ‏مَعَ أُمِّ الْمُؤْمِنِينَ ‏ ‏فَرَأَتْ عَلَى امْرَأَةٍ ‏ ‏بُرْدًا ‏ ‏فِيهِ تَصْلِيبٌ فَقَالَتْ ‏ ‏أُمُّ الْمُؤْمِنِينَ ‏ ‏اطْرَحِيهِ اطْرَحِيهِ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا رَأَى نَحْوَ هَذَا ‏ ‏قَضَبَهُ ‏","","",""],[23940,23940,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جَعْفَرِ بْنِ الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبَّادَ بْنَ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏عَائِشَةَ ‏ ‏تُحَدِّثُ ‏ ‏أَنَّ رَجُلًا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّهُ قَدْ احْتَرَقَ فَسَأَلَهُ مَا شَأْنُهُ فَقَالَ ‏ ‏أَصَابَ أَهْلَهُ فِي رَمَضَانَ فَأَتَاهُ ‏ ‏مِكْتَلٌ ‏ ‏يُدْعَى ‏ ‏الْعَرَقَ ‏ ‏فِيهِ تَمْرٌ فَقَالَ أَيْنَ الْمُحْتَرِقُ فَقَامَ الرَّجُلُ فَقَالَ تَصَدَّقْ بِهَذَا ‏","","",""],[23941,23941,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَامِرِ بْنِ رَبِيعَةَ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏كَانَتْ تُحَدِّثُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَهِرَ ذَاتَ لَيْلَةٍ وَهِيَ إِلَى جَنْبِهِ قَالَتْ فَقُلْتُ مَا شَأْنُكَ يَا رَسُولَ اللَّهِ قَالَتْ فَقَالَ ‏ ‏لَيْتَ رَجُلًا صَالِحًا مِنْ أَصْحَابِي يَحْرُسُنِي اللَّيْلَةَ قَالَ فَبَيْنَا أَنَا عَلَى ذَلِكَ إِذْ سَمِعْتُ صَوْتَ السِّلَاحِ فَقَالَ مَنْ هَذَا قَالَ أَنَا ‏ ‏سَعْدُ بْنُ مَالِكٍ ‏ ‏فَقَالَ مَا جَاءَ بِكَ قَالَ جِئْتُ لِأَحْرُسَكَ يَا رَسُولَ اللَّهِ قَالَتْ فَسَمِعْتُ ‏ ‏غَطِيطَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي نَوْمِهِ ‏","","",""],[23942,23942,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ يَعْنِي ابْنَ حُسَيْنٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أُهْدِيَتْ ‏ ‏لِحَفْصَةَ ‏ ‏شَاةٌ وَنَحْنُ صَائِمَتَانِ فَفَطَّرَتْنِي فَكَانَتْ ابْنَةَ أَبِيهَا فَلَمَّا دَخَلَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَكَرْنَا ذَلِكَ لَهُ فَقَالَ أَبْدِلَا يَوْمًا مَكَانَهُ ‏","","",""],[23943,23943,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏وَعَمْرَةَ بِنْتِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏أُمَّ حَبِيبَةَ بِنْتَ جَحْشٍ ‏ ‏اسْتُحِيضَتْ سَبْعَ سِنِينَ وَكَانَتْ امْرَأَةَ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏فَسَأَلَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا هَذَا ‏ ‏عِرْقٌ ‏ ‏وَلَيْسَتْ بِحَيْضَةٍ فَاغْتَسِلِي وَصَلِّي ‏ ‏قَالَ ‏ ‏فَكَانَتْ تَغْتَسِلُ عِنْدَ كُلِّ صَلَاةٍ ‏","","",""],[23944,23944,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عَبْدِ الرَّحْمَنِ بْنِ حَاطِبٍ ‏ ‏قَالَ ‏ ‏كَانَتْ ‏ ‏عَائِشَةُ ‏ ‏تَقُولُ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثَةَ أَنْوَاعٍ ‏ ‏فَمِنَّا مَنْ أَهَلَّ بِحَجٍّ وَعُمْرَةٍ وَمِنَّا مَنْ أَهَلَّ بِحَجٍّ مُفْرَدٍ وَمِنَّا مَنْ أَهَلَّ بِعُمْرَةٍ فَمَنْ كَانَ أَهَلَّ بِحَجٍّ وَعُمْرَةٍ مَعًا لَمْ يَحِلَّ مِنْ شَيْءٍ مِمَّا حَرَّمَ اللَّهُ عَزَّ وَجَلَّ عَلَيْهِ حَتَّى يَقْضِيَ حَجَّهُ وَمَنْ أَهَلَّ بِعُمْرَةٍ ثُمَّ طَافَ ‏ ‏بِالْبَيْتِ ‏ ‏وَسَعَى بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏وَقَصَّرَ أَحَلَّ مِمَّا حُرِمَ مِنْهُ حَتَّى يَسْتَقْبِلَ حَجًّا ‏","","",""],[23945,23945,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَلْقَمَةَ بْنِ وَقَّاصٍ ‏ ‏قَالَ أَخْبَرَتْنِي ‏ ‏عَائِشَةُ ‏ ‏قَالَتْ ‏ ‏خَرَجْتُ يَوْمَ ‏ ‏الْخَنْدَقِ ‏ ‏أَقْفُو ‏ ‏آثَارَ النَّاسِ قَالَتْ فَسَمِعْتُ وَئِيدَ الْأَرْضِ وَرَائِي ‏ ‏يَعْنِي حِسَّ الْأَرْضِ ‏ ‏قَالَتْ فَالْتَفَتُّ فَإِذَا أَنَا ‏ ‏بِسَعْدِ بْنِ مُعَاذٍ ‏ ‏وَمَعَهُ ابْنُ أَخِيهِ ‏ ‏الْحَارِثُ بْنُ أَوْسٍ ‏ ‏يَحْمِلُ ‏ ‏مِجَنَّهُ ‏ ‏قَالَتْ فَجَلَسْتُ إِلَى الْأَرْضِ فَمَرَّ ‏ ‏سَعْدٌ ‏ ‏وَعَلَيْهِ ‏ ‏دِرْعٌ ‏ ‏مِنْ حَدِيدٍ قَدْ خَرَجَتْ مِنْهَا أَطْرَافُهُ فَأَنَا أَتَخَوَّفُ عَلَى أَطْرَافِ ‏ ‏سَعْدٍ ‏ ‏قَالَتْ وَكَانَ ‏ ‏سَعْدٌ ‏ ‏مِنْ أَعْظَمِ النَّاسِ وَأَطْوَلِهِمْ قَالَتْ فَمَرَّ وَهُوَ ‏ ‏يَرْتَجِزُ ‏ ‏وَيَقُولُ ‏ ‏لَيْتَ قَلِيلًا يُدْرِكُ ‏ ‏الْهَيْجَا ‏ ‏جَمَلْ ‏ ‏مَا أَحْسَنَ الْمَوْتَ إِذَا حَانَ ‏ ‏الْأَجَلْ ‏ ‏قَالَتْ فَقُمْتُ فَاقْتَحَمْتُ حَدِيقَةً فَإِذَا فِيهَا نَفَرٌ مِنْ الْمُسْلِمِينَ وَإِذَا فِيهِمْ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏وَفِيهِمْ رَجُلٌ عَلَيْهِ ‏ ‏سَبْغَةٌ لَهُ ‏ ‏يَعْنِي مِغْفَرًا ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏مَا جَاءَ بِكِ لَعَمْرِي وَاللَّهِ إِنَّكِ لَجَرِيئَةٌ وَمَا يُؤْمِنُكِ أَنْ يَكُونَ بَلَاءٌ أَوْ يَكُونَ تَحَوُّزٌ قَالَتْ فَمَا زَالَ يَلُومُنِي حَتَّى تَمَنَّيْتُ أَنَّ الْأَرْضَ انْشَقَّتْ لِي سَاعَتَئِذٍ فَدَخَلْتُ فِيهَا قَالَتْ فَرَفَعَ الرَّجُلُ ‏ ‏السَّبْغَةَ عَنْ وَجْهِهِ فَإِذَا ‏ ‏طَلْحَةُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏فَقَالَ يَا ‏ ‏عُمَرُ ‏ ‏وَيْحَكَ إِنَّكَ قَدْ أَكْثَرْتَ مُنْذُ الْيَوْمَ وَأَيْنَ ‏ ‏التَّحَوُّزُ ‏ ‏أَوْ الْفِرَارُ إِلَّا إِلَى اللَّهِ عَزَّ وَجَلَّ قَالَتْ ‏ ‏وَيَرْمِي ‏ ‏سَعْدًا ‏ ‏رَجُلٌ مِنْ الْمُشْرِكِينَ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏يُقَالُ لَهُ ‏ ‏ابْنُ الْعَرِقَةِ ‏ ‏بِسَهْمٍ لَهُ فَقَالَ لَهُ خُذْهَا وَأَنَا ‏ ‏ابْنُ الْعَرَقَةِ ‏ ‏فَأَصَابَ ‏ ‏أَكْحَلَهُ ‏ ‏فَقَطَعَهُ فَدَعَا اللَّهَ عَزَّ وَجَلَّ ‏ ‏سَعْدٌ ‏ ‏فَقَالَ اللَّهُمَّ لَا تُمِتْنِي حَتَّى تُقِرَّ عَيْنِي مِنْ ‏ ‏قُرَيْظَةَ ‏ ‏قَالَتْ وَكَانُوا حُلَفَاءَهُ ‏ ‏وَمَوَالِيَهُ ‏ ‏فِي الْجَاهِلِيَّةِ قَالَتْ فَرَقَى كَلْمُهُ وَبَعَثَ اللَّهُ عَزَّ وَجَلَّ الرِّيحَ عَلَى الْمُشْرِكِينَ فَكَفَى اللَّهُ عَزَّ وَجَلَّ الْمُؤْمِنِينَ الْقِتَالَ وَكَانَ اللَّهُ عَزَّ وَجَلَّ قَوِيًّا عَزِيزًا فَلَحِقَ ‏ ‏أَبُو سُفْيَانَ ‏ ‏وَمَنْ مَعَهُ ‏ ‏بِتِهَامَةَ ‏ ‏وَلَحِقَ ‏ ‏عُيَيْنَةُ بْنُ بَدْرٍ ‏ ‏وَمَنْ مَعَهُ ‏ ‏بِنَجْدٍ ‏ ‏وَرَجَعَتْ ‏ ‏بَنُو قُرَيْظَةَ ‏ ‏فَتَحَصَّنُوا فِي صَيَاصِيهِمْ وَرَجَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَوَضَعَ السِّلَاحَ وَأَمَرَ ‏ ‏بِقُبَّةٍ ‏ ‏مِنْ ‏ ‏أَدَمٍ ‏ ‏فَضُرِبَتْ ‏ ‏عَلَى ‏ ‏سَعْدٍ ‏ ‏فِي الْمَسْجِدِ قَالَتْ فَجَاءَهُ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏وَإِنَّ عَلَى ‏ ‏ثَنَايَاهُ ‏ ‏لَنَقْعُ الْغُبَارِ فَقَالَ أَقَدْ وَضَعْتَ السِّلَاحَ وَاللَّهِ مَا وَضَعَتْ الْمَلَائِكَةُ بَعْدُ السِّلَاحَ اخْرُجْ إِلَى ‏ ‏بَنِي قُرَيْظَةَ ‏ ‏فَقَاتِلْهُمْ قَالَتْ فَلَبِسَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَأْمَتَهُ وَأَذَّنَ فِي النَّاسِ بِالرَّحِيلِ أَنْ يَخْرُجُوا فَخَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَرَّ عَلَى ‏ ‏بَنِي غَنْمٍ ‏ ‏وَهُمْ جِيرَانُ الْمَسْجِدِ حَوْلَهُ فَقَالَ مَنْ مَرَّ بِكُمْ فَقَالُوا مَرَّ بِنَا ‏ ‏دِحْيَةُ الْكَلْبِيُّ ‏ ‏وَكَانَ ‏ ‏دِحْيَةُ الْكَلْبِيُّ ‏ ‏تُشْبِهُ لِحْيَتُهُ وَسِنُّهُ وَوَجْهُهُ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَقَالَتْ فَأَتَاهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَاصَرَهُمْ خَمْسًا وَعِشْرِينَ لَيْلَةً فَلَمَّا اشْتَدَّ حَصْرُهُمْ وَاشْتَدَّ الْبَلَاءُ قِيلَ لَهُمْ انْزِلُوا عَلَى حُكْمِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاسْتَشَارُوا ‏ ‏أَبَا لُبَابَةَ بْنَ عَبْدِ الْمُنْذِرِ ‏ ‏فَأَشَارَ إِلَيْهِمْ أَنَّهُ الذَّبْحُ قَالُوا نَنْزِلُ عَلَى حُكْمِ ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْزِلُوا عَلَى حُكْمِ ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏ ‏فَنَزَلُوا وَبَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏ ‏فَأُتِيَ بِهِ عَلَى حِمَارٍ عَلَيْهِ ‏ ‏إِكَافٌ ‏ ‏مِنْ لِيفٍ قَدْ حُمِلَ عَلَيْهِ ‏ ‏وَحَفَّ ‏ ‏بِهِ قَوْمُهُ فَقَالُوا يَا ‏ ‏أَبَا عَمْرٍو ‏ ‏حُلَفَاؤُكَ وَمَوَالِيكَ وَأَهْلُ النِّكَايَةِ وَمَنْ قَدْ عَلِمْتَ قَالَتْ وَأَنَّى لَا يُرْجِعُ إِلَيْهِمْ شَيْئًا وَلَا يَلْتَفِتُ إِلَيْهِمْ حَتَّى إِذَا ‏ ‏دَنَا ‏ ‏مِنْ دُورِهِمْ الْتَفَتَ إِلَى قَوْمِهِ فَقَالَ قَدْ آنَ لِي أَنْ لَا أُبَالِيَ فِي اللَّهِ لَوْمَةَ لَائِمٍ قَالَ قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏فَلَمَّا طَلَعَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قُومُوا إِلَى سَيِّدِكُمْ فَأَنْزَلُوهُ فَقَالَ ‏ ‏عُمَرُ ‏ ‏سَيِّدُنَا اللَّهُ عَزَّ وَجَلَّ قَالَ أَنْزِلُوهُ فَأَنْزَلُوهُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْكُمْ فِيهِمْ قَالَ ‏ ‏سَعْدٌ ‏ ‏فَإِنِّي أَحْكُمُ فِيهِمْ أَنْ تُقْتَلَ مُقَاتِلَتُهُمْ ‏ ‏وَتُسْبَى ذَرَارِيُّهُمْ وَتُقْسَمَ أَمْوَالُهُمْ ‏ ‏وَقَالَ ‏ ‏يَزِيدُ ‏ ‏بِبَغْدَادَ ‏ ‏وَيُقْسَمُ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ حَكَمْتَ فِيهِمْ بِحُكْمِ اللَّهِ عَزَّ وَجَلَّ وَحُكْمِ رَسُولِهِ قَالَتْ ثُمَّ دَعَا ‏ ‏سَعْدٌ ‏ ‏قَالَ اللَّهُمَّ إِنْ كُنْتَ أَبْقَيْتَ عَلَى نَبِيِّكَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ حَرْبِ ‏ ‏قُرَيْشٍ ‏ ‏شَيْئًا فَأَبْقِنِي لَهَا وَإِنْ كُنْتَ قَطَعْتَ الْحَرْبَ بَيْنَهُ وَبَيْنَهُمْ فَاقْبِضْنِي إِلَيْكَ قَالَتْ فَانْفَجَرَ كَلْمُهُ وَكَانَ قَدْ بَرِئَ حَتَّى مَا يُرَى مِنْهُ إِلَّا مِثْلُ ‏ ‏الْخُرْصِ ‏ ‏وَرَجَعَ إِلَى ‏ ‏قُبَّتِهِ ‏ ‏الَّتِي ضَرَبَ عَلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَحَضَرَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏قَالَتْ فَوَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ إِنِّي لَأَعْرِفُ بُكَاءَ ‏ ‏عُمَرَ ‏ ‏مِنْ بُكَاءِ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَأَنَا فِي حُجْرَتِي وَكَانُوا كَمَا قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏رُحَمَاءُ بَيْنَهُمْ ‏} ‏قَالَ ‏ ‏عَلْقَمَةُ ‏ ‏قُلْتُ أَيْ ‏ ‏أُمَّهْ فَكَيْفَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصْنَعُ قَالَتْ كَانَتْ عَيْنُهُ لَا تَدْمَعُ عَلَى أَحَدٍ وَلَكِنَّهُ كَانَ إِذَا ‏ ‏وَجِدَ فَإِنَّمَا هُوَ آخِذٌ بِلِحْيَتِهِ ‏","","",""],[23946,23946,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ مَيْمُونٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ يَسَارٍ ‏ ‏قَالَ أَخْبَرَتْنِي ‏ ‏عَائِشَةُ ‏ ‏أَنَّهَا كَانَتْ تَغْسِلُ ‏ ‏الْمَنِيَّ ‏ ‏مِنْ ثَوْبِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَخْرُجُ ‏ ‏فَيُصَلِّي وَأَنَا أَنْظُرُ إِلَى الْبُقَعِ فِي ثَوْبِهِ مِنْ أَثَرِ الْغَسْلِ ‏","","",""],[23947,23947,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عَبَّادِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ صَلَّى صَلَاةً لَمْ يَقْرَأْ فِيهَا ‏ ‏بِأُمِّ الْقُرْآنِ ‏ ‏فَهِيَ ‏ ‏خِدَاجٌ ‏","","",""],[23948,23948,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏وَاعَدَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جِبْرِيلُ ‏ ‏فِي سَاعَةٍ أَنْ يَأْتِيَهُ فِيهَا ‏ ‏فَرَاثَ ‏ ‏عَلَيْهِ أَنْ يَأْتِيَهُ فِيهَا فَخَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَجَدَهُ بِالْبَابِ قَائِمًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي انْتَظَرْتُكَ لِمِيعَادِكَ فَقَالَ إِنَّ فِي الْبَيْتِ كَلْبًا وَلَا نَدْخُلُ بَيْتًا فِيهِ كَلْبٌ وَلَا صُورَةٌ وَكَانَ تَحْتَ سَرِيرِ ‏ ‏عَائِشَةَ ‏ ‏جِرْوُ ‏ ‏كَلْبٍ فَأَمَرَ بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأُخْرِجَ ثُمَّ أَمَرَ بِالْكِلَابِ حِينَ أَصْبَحَ فَقُتِلَتْ ‏","","",""],[23949,23949,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏كَيْفَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُومُ قَالَتْ كَانَ ‏ ‏يَصُومُ حَتَّى نَقُولَ لَا يُفْطِرُ وَيُفْطِرُ حَتَّى نَقُولَ لَا يَصُومُ لَمْ أَرَهُ فِي شَهْرٍ أَكْثَرَ صِيَامًا مِنْهُ فِي شَعْبَانَ كَانَ يَصُومُ شَعْبَانَ كُلَّهُ إِلَّا قَلِيلًا بَلْ كَانَ يَصُومُ شَعْبَانَ كُلَّهُ ‏","","",""],[23950,23950,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْأَصْبَغُ ‏ ‏عَنْ ‏ ‏ثَوْرِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَبِيعَةُ الْجُرَشِيُّ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏فَقُلْتُ مَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِذَا قَامَ مِنْ اللَّيْلِ وَبِمَ كَانَ يَسْتَفْتِحُ قَالَتْ كَانَ ‏ ‏يُكَبِّرُ عَشْرًا وَيُسَبِّحُ عَشْرًا وَيُهَلِّلُ عَشْرًا وَيَسْتَغْفِرُ عَشْرًا وَيَقُولُ اللَّهُمَّ اغْفِرْ لِي وَاهْدِنِي وَارْزُقْنِي عَشْرًا وَيَقُولُ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الضِّيقِ يَوْمَ الْحِسَابِ عَشْرًا ‏","","",""],[23951,23951,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْحَجَّاجُ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَمَيْتُمْ وَحَلَقْتُمْ فَقَدْ حَلَّ لَكُمْ الطِّيبُ وَالثِّيَابُ وَكُلُّ شَيْءٍ إِلَّا النِّسَاءَ ‏","","",""],[23952,23952,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ أَنْ ‏ ‏يُبَاشِرَ ‏ ‏إِحْدَانَا وَهِيَ حَائِضٌ أَمَرَهَا ‏ ‏فَاتَّزَرَتْ ‏ ‏وَإِذَا أَرَادَ أَنْ يَنَامَ وَهُوَ جُنُبٌ تَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ ‏","","",""],[23953,23953,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي مَا بَيْنَ أَنْ يَفْرَغَ مِنْ صَلَاةِ الْعِشَاءِ إِلَى الْفَجْرِ إِحْدَى عَشْرَةَ رَكْعَةً يُسَلِّمُ فِي كُلِّ ثِنْتَيْنِ وَيُوتِرُ بِوَاحِدَةٍ وَيَسْجُدُ فِي سَجْدَتِهِ بِقَدْرِ مَا يَقْرَأُ أَحَدُكُمْ خَمْسِينَ آيَةً قَبْلَ أَنْ يَرْفَعَ رَأْسَهُ فَإِذَا سَكَتَ الْمُؤَذِّنُ مِنْ الْأَذَانِ الْأَوَّلِ قَامَ فَرَكَعَ رَكْعَتَيْنِ خَفِيفَتَيْنِ ثُمَّ اضْطَجَعَ عَلَى شِقِّهِ الْأَيْمَنِ حَتَّى يَأْتِيَهُ الْمُؤَذِّنُ فَيَخْرُجَ مَعَهُ ‏","","",""],[23954,23954,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏بُدَيْلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَأْكُلُ طَعَامًا فِي سِتَّةِ نَفَرٍ مِنْ أَصْحَابِهِ فَجَاءَ أَعْرَابِيٌّ فَأَكَلَهُ بِلُقْمَتَيْنِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَا إِنَّهُ لَوْ كَانَ ذَكَرَ اسْمَ اللَّهِ لَكَفَاكُمْ ‏ ‏فَإِذَا أَكَلَ أَحَدُكُمْ طَعَامًا فَلْيَذْكُرْ اسْمَ اللَّهِ فَإِنْ نَسِيَ أَنْ يَذْكُرَ اسْمَ اللَّهِ فِي أَوَّلِهِ فَلْيَقُلْ بِسْمِ اللَّهِ أَوَّلَهُ وَآخِرَهُ ‏","","",""],[23955,23955,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ بْنُ الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ حَفْصٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سَأَلَهَا أَخُوهَا مِنْ الرَّضَاعَةِ عَنْ غُسْلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْجَنَابَةِ ‏ ‏فَدَعَتْ بِمَاءٍ قَدْرَ ‏ ‏الصَّاعِ ‏ ‏فَاغْتَسَلَتْ وَصَبَّتْ عَلَى رَأْسِهَا ثَلَاثًا ‏","","",""],[23956,23956,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ غُسْلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْجَنَابَةِ فَقَالَتْ كَانَ ‏ ‏يَغْسِلُ يَدَيْهِ ثَلَاثًا ثُمَّ يَغْسِلُ فَرْجَهُ ثُمَّ يَغْسِلُ يَدَيْهِ ثُمَّ يَتَمَضْمَضُ وَيَسْتَنْشِقُ ثُمَّ يَصُبُّ عَلَى رَأْسِهِ ثُمَّ يُفْرِغُ عَلَى سَائِرِ جَسَدِهِ ‏","","",""],[23957,23957,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏أَنَّ امْرَأَةً قَالَتْ ‏ ‏لِعَائِشَةَ ‏ ‏أَتَجْزِي إِحْدَانَا صَلَاتَهَا إِذَا كَانَتْ حَائِضًا قَالَتْ ‏ ‏أَحَرُورِيَّةٌ ‏ ‏أَنْتِ قَدْ ‏ ‏كُنَّا نَحِيضُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَا يَأْمُرُنَا بِقَضَاءِ الصَّلَاةِ ‏","","",""],[23958,23958,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أُتِيَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِضَبٍّ فَلَمْ يَأْكُلْهُ فَقُلْتُ أَلَا نُطْعِمُهُ الْمَسَاكِينَ قَالَ لَا تُطْعِمُوهُمْ مِمَّا لَا تَأْكُلُونَ ‏","","",""],[23959,23959,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَمَّادٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏وحَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْسِمُ بَيْنَ نِسَائِهِ فَيَعْدِلُ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏وَيَقُولُ هَذِهِ قِسْمَتِي ‏ ‏ثُمَّ يَقُولُ اللَّهُمَّ هَذَا فِعْلِي فِيمَا أَمْلِكُ فَلَا تَلُمْنِي فِيمَا تَمْلِكُ وَلَا أَمْلِكُ ‏","","",""],[23960,23960,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَوُادَ الْهَاشِمِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ أَرَأَيْتِ قَوْلَ اللَّهِ عَزَّ وَجَلَّ ‏ { ‏إِنَّ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةَ ‏ ‏مِنْ شَعَائِرِ اللَّهِ فَمَنْ حَجَّ ‏ ‏الْبَيْتَ ‏ ‏أَوْ اعْتَمَرَ فَلَا جُنَاحَ عَلَيْهِ أَنْ يَطَّوَّفَ بِهِمَا ‏} ‏قَالَ فَقُلْتُ فَوَاللَّهِ مَا عَلَى أَحَدٍ جُنَاحٌ أَنْ لَا يَطَّوَّفَ بِهِمَا فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏بِئْسَمَا قُلْتَ يَا ابْنَ أُخْتِي إِنَّهَا لَوْ كَانَتْ عَلَى مَا أَوَّلْتَهَا كَانَتْ فَلَا جُنَاحَ عَلَيْهِ أَنْ لَا يَطَّوَّفَ بِهِمَا وَلَكِنَّهَا إِنَّمَا أُنْزِلَتْ أَنَّ ‏ ‏الْأَنْصَارَ ‏ ‏كَانُوا قَبْلَ أَنْ يُسْلِمُوا يُهِلُّونَ لِمَنَاةَ الطَّاغِيَةِ الَّتِي كَانُوا يَعْبُدُونَ عِنْدَ ‏ ‏الْمُشَلَّلِ ‏ ‏وَكَانَ مَنْ أَهَلَّ لَهَا تَحَرَّجَ أَنْ يَطَّوَّفَ ‏ ‏بِالصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏فَسَأَلُوا عَنْ ذَلِكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّا كُنَّا نَتَحَرَّجُ أَنْ نَطَّوَّفَ ‏ ‏بِالصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏فِي الْجَاهِلِيَّةِ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏إِنَّ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةَ ‏ ‏مِنْ شَعَائِرِ اللَّهِ ‏ ‏إِلَى قَوْلِهِ ‏ ‏فَلَا جُنَاحَ عَلَيْهِ أَنْ يَطَّوَّفَ بِهِمَا ‏} ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏ثُمَّ قَدْ سَنَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الطَّوَافَ بِهِمَا فَلَيْسَ يَنْبَغِي لِأَحَدٍ أَنْ يَدَعَ الطَّوَافَ بِهِمَا ‏","","",""],[23961,23961,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ كَيْسَانَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْيَوْمِ الَّذِي بُدِئَ فِيهِ فَقُلْتُ وَا ‏ ‏رَأْسَاهْ فَقَالَ ‏ ‏وَدِدْتُ أَنَّ ذَلِكَ كَانَ وَأَنَا حَيٌّ فَهَيَّأْتُكِ وَدَفَنْتُكِ قَالَتْ فَقُلْتُ غَيْرَى كَأَنِّي بِكَ فِي ذَلِكَ الْيَوْمِ عَرُوسًا بِبَعْضِ نِسَائِكَ قَالَ وَأَنَا وَا ‏ ‏رَأْسَاهْ ‏ ‏ادْعُوا إِلَيَّ أَبَاكِ وَأَخَاكِ حَتَّى أَكْتُبَ ‏ ‏لِأَبِي بَكْرٍ ‏ ‏كِتَابًا فَإِنِّي أَخَافُ أَنْ يَقُولَ قَائِلٌ ‏ ‏وَيَتَمَنَّى مُتَمَنٍّ أَنَا أَوْلَى وَيَأْبَى اللَّهُ عَزَّ وَجَلَّ وَالْمُؤْمِنُونَ إِلَّا ‏ ‏أَبَا بَكْرٍ ‏","","",""],[23962,23962,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رُفِعَ الْقَلَمُ عَنْ ثَلَاثَةٍ عَنْ النَّائِمِ حَتَّى يَسْتَيْقِظَ وَعَنْ الْمُبْتَلَى حَتَّى يَبْرَأَ وَعَنْ الصَّبِيِّ حَتَّى يَعْقِلَ ‏","","",""],[23963,23963,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏صَخْرُ بْنُ جُوَيْرِيَةَ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏أَبِي خَلَفٍ ‏ ‏أَنَّهُ دَخَلَ مَعَ ‏ ‏عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَسَأَلَهَا ‏ ‏عُبَيْدُ بْنُ عُمَيْرٍ ‏ ‏كَيْفَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ هَذِهِ الْآيَةَ الَّذِينَ يَأْتُونَ مَا أَتَوْا ‏ ‏أَوْ يُؤْتُونَ مَا أَتَوْا ‏ ‏فَقَالَتْ أَيُّهُمَا أَحَبُّ إِلَيْكَ فَقَالَ وَاللَّهِ لَأَحَدُهُمَا أَحَبُّ إِلَيَّ مِنْ كَذَا وَكَذَا قَالَتْ أَيَّتُهُمَا قَالَ ‏ ‏الَّذِينَ يَأْتُونَ مَا أَتَوْا فَقَالَتْ أَشْهَدُ لَكَذَلِكَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَؤُهَا وَكَذَاكَ أُنْزِلَتْ وَلَكِنَّ الْهِجَاءَ حُرِّفَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏صَخْرُ بْنُ جُوَيْرِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ الْمَكِّيُّ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو خَلَفٍ ‏ ‏مَوْلَى ‏ ‏بَنِي جُمَحٍ ‏ ‏أَنَّهُ دَخَلَ مَعَ ‏ ‏عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏عَلَى ‏ ‏أُمِّ الْمُؤْمِنِينَ عَائِشَةَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[23964,23964,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏جُعِلَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بُرْدَةٌ سَوْدَاءُ مِنْ صُوفٍ فَذَكَرَ بَيَاضَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَسَوَادَهَا فَلَمَّا عَرِقَ وَجَدَ مِنْهَا رِيحَ الصُّوفِ فَقَذَفَهَا ‏ ‏قَالَ وَأَحْسِبُهُ قَدْ قَالَتْ كَانَ يُعْجِبُهُ الرِّيحُ الطَّيِّبَةُ ‏","","",""],[23965,23965,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏جَعْفَرُ بْنُ كَيْسَانَ ‏ ‏وَيَحْيَى بْنُ إِسْحَاقَ ‏ ‏وَعَفَّانُ ‏ ‏الْمَعْنَى ‏ ‏وَهَذَا لَفْظُ حَدِيثِ ‏ ‏يَزِيدَ ‏ ‏لَمْ يَخْتَلِفُوا فِي الْإِسْنَادِ وَالْمَعْنَى ‏ ‏قَالَا أَنَا ‏ ‏جَعْفَرُ بْنُ كَيْسَانَ الْعَدَوِيُّ ‏ ‏قَالَ حَدَّثَتْنَا ‏ ‏مُعَاذَةُ بِنْتُ عَبْدِ اللَّهِ الْعَدَوِيَّةُ ‏ ‏قَالَتْ ‏ ‏دَخَلْتُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَقَالَتْ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تَفْنَى أُمَّتِي إِلَّا بِالطَّعْنِ وَالطَّاعُونِ قُلْتُ يَا رَسُولَ اللَّهِ هَذَا الطَّعْنُ قَدْ عَرَفْنَاهُ فَمَا الطَّاعُونُ قَالَ ‏ ‏غُدَّةٌ ‏ ‏كَغُدَّةِ الْبَعِيرِ الْمُقِيمُ بِهَا كَالشَّهِيدِ وَالْفَارُّ مِنْهَا كَالْفَارِّ مِنْ الزَّحْفِ ‏","","",""],[23966,23966,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ سَخْبَرَةَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَعْظَمُ النِّسَاءِ بَرَكَةً أَيْسَرُهُنَّ ‏ ‏مَئُونَةً ‏","","",""],[23967,23967,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏اللَّهُمَّ اجْعَلْنِي مِنْ الَّذِينَ إِذَا أَحْسَنُوا اسْتَبْشَرُوا وَإِذَا أَسَاءُوا اسْتَغْفَرُوا ‏","","",""],[23968,23968,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شَيْبَةُ الْخُضَرِيُّ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏فَحَدَّثَنَا ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ثَلَاثٌ أَحْلِفُ عَلَيْهِنَّ لَا يَجْعَلُ اللَّهُ عَزَّ وَجَلَّ مَنْ لَهُ سَهْمٌ فِي الْإِسْلَامِ كَمَنْ لَا سَهْمَ لَهُ فَأَسْهُمُ الْإِسْلَامِ ثَلَاثَةٌ الصَّلَاةُ وَالصَّوْمُ وَالزَّكَاةُ وَلَا يَتَوَلَّى اللَّهُ عَزَّ وَجَلَّ عَبْدًا فِي الدُّنْيَا ‏ ‏فَيُوَلِّيهِ غَيْرَهُ يَوْمَ الْقِيَامَةِ وَلَا يُحِبُّ رَجُلٌ قَوْمًا إِلَّا جَعَلَهُ اللَّهُ عَزَّ وَجَلَّ مَعَهُمْ وَالرَّابِعَةُ لَوْ حَلَفْتُ عَلَيْهَا رَجَوْتُ أَنْ لَا آثَمَ لَا يَسْتُرُ اللَّهُ عَزَّ وَجَلَّ عَبْدًا فِي الدُّنْيَا إِلَّا سَتَرَهُ يَوْمَ الْقِيَامَةِ ‏ ‏فَقَالَ ‏ ‏عُمَرُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏إِذَا سَمِعْتُمْ مِثْلَ هَذَا الْحَدِيثِ مِنْ مِثْلِ ‏ ‏عُرْوَةَ ‏ ‏يَرْوِيهِ عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاحْفَظُوهُ ‏","","",""],[23969,23969,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏وَعَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏سُمَيَّةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏وَجَدَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏صَفِيَّةَ بِنْتِ حُيَيٍّ ‏ ‏فَقَالَتْ لِي هَلْ لَكِ إِلَى أَنْ تُرْضِينَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنِّي وَأَجْعَلُ لَكِ يَوْمِي قُلْتُ نَعَمْ فَأَخَذَتْ خِمَارًا لَهَا مَصْبُوغًا بِزَعْفَرَانٍ فَرَشَّتْهُ بِالْمَاءِ ثُمَّ اخْتَمَرَتْ بِهِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏لِيَفُوحَ رِيحُهُ ‏ ‏ثُمَّ دَخَلَتْ عَلَيْهِ فِي يَوْمِهَا فَجَلَسَتْ إِلَى جَنْبِهِ فَقَالَ ‏ ‏إِلَيْكِ يَا ‏ ‏عَائِشَةُ ‏ ‏فَلَيْسَ هَذَا يَوْمَكِ فَقُلْتُ فَضْلُ اللَّهِ ‏ ‏يُؤْتِيهِ مَنْ يَشَاءُ ثُمَّ أَخْبَرْتُهُ خَبَرِي ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فَرَضِيَ عَنْهَا ‏","","",""],[23970,23970,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي الضُّحَى أَرْبَعًا وَيَزِيدُ مَا شَاءَ ‏","","",""],[23971,23971,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏جَعْفَرُ بْنُ بُرْدٍ ‏ ‏قَالَ حَدَّثَتْنَا ‏ ‏أُمُّ سَالِمٍ الرَّاسِبِيَّةُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أُتِيَ بِاللَّبَنِ قَالَ ‏ ‏كَمْ فِي الْبَيْتِ بَرَكَةً ‏ ‏أَوْ بَرَكَتَيْنِ ‏","","",""],[23972,23972,"","","‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ عِيسَى ‏ ‏أَخْبَرَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا نُورَثُ مَا تَرَكْنَا فَهُوَ ‏ ‏صَدَقَةٌ ‏","","",""],[23973,23973,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ شُرَيْحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ الصَّلَاةِ بَعْدَ الْعَصْرِ فَقَالَتْ صَلِّ إِنَّمَا ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَوْمَكَ أَهْلَ ‏ ‏الْيَمَنِ ‏ ‏عَنْ الصَّلَاةِ إِذَا طَلَعَتْ الشَّمْسُ ‏","","",""],[23974,23974,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ الرِّشْكِ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُومُ ثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ قَالَتْ فَقُلْتُ مِنْ أَيِّهِ كَانَ فَقَالَتْ لَمْ يَكُنْ يُبَالِي مِنْ أَيِّهِ كَانَ ‏","","",""],[23975,23975,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ غُنْدَرٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ جَعْفَرٍ الْمَخْرَمِيُّ ‏ ‏أَخْبَرَنِي ‏ ‏سَعْدُ بْنُ إِبْرَاهِيمَ ‏ ‏أَنَّ رَجُلًا أَوْصَى فِي مَسَاكِنَ لَهُ بِثُلُثِ كُلِّ مَسْكَنٍ لِإِنْسَانٍ فَسَأَلْتُ ‏ ‏الْقَاسِمَ بْنَ مُحَمَّدٍ ‏ ‏فَقَالَ اجْمَعْ ثَلَاثَةً فِي مَكَانِ وَاحِدٍ فَإِنِّي سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ عَمِلَ عَمَلًا لَيْسَ عَلَيْهِ أَمْرُنَا فَأَمْرُهُ رَدٌّ ‏","","",""],[23976,23976,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏وَمُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ قَوْمًا اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ ‏ ‏وَقَالَ ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ قَوْمًا ‏ ‏وَقَالَ ‏ ‏الْخَفَّافُ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَعَنَ اللَّهُ قَوْمًا اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ ‏","","",""],[23977,23977,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَقَدْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي وَأَنَا عَنْ يَمِينِهِ وَعَنْ شِمَالِهِ مُضْطَجِعَةٌ ‏","","",""],[23978,23978,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاضِعًا يَدَيْهِ عَلَى ‏ ‏مَعْرَفَةِ ‏ ‏فَرَسٍ وَهُوَ يُكَلِّمُ رَجُلًا قُلْتُ رَأَيْتُكَ وَاضِعًا يَدَيْكَ عَلَى ‏ ‏مَعْرَفَةِ ‏ ‏فَرَسِ ‏ ‏دِحْيَةَ الْكَلْبِيِّ ‏ ‏وَأَنْتَ تُكَلِّمُهُ قَالَ ‏ ‏وَرَأَيْتِيهِ قَالَتْ نَعَمْ قَالَ ‏ ‏ذَاكَ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏وَهُوَ يُقْرِئُكِ السَّلَامَ قَالَتْ وَعَلَيْهِ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ جَزَاهُ اللَّهُ خَيْرًا مِنْ صَاحِبٍ وَدَخِيلٍ فَنِعْمَ الصَّاحِبُ وَنِعْمَ الدَّخِيلُ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏الدَّخِيلُ الضَّيْفُ ‏","","",""],[23979,23979,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي عِيَاضٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏قَدْ كَانَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي وَإِنَّ بَعْضَ ‏ ‏مِرْطِي ‏ ‏عَلَيْهِ ‏","","",""],[23980,23980,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْمَاعِيلَ بْنِ أَبِي فُدَيْكٍ الدِّيْلِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْمَاعِيلَ بْنِ أَبِي حَبِيبَةَ الْأَشْهَلِيُّ ‏ ‏عَنْ ‏ ‏دَوُادَ بْنِ الْحُصَيْنِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏السِّوَاكُ مَطْيَبَةٌ لِلْفَمِ مَرْضَاةٌ لِلرَّبِّ وَفِي الْحَبَّةِ السَّوْدَاءِ شِفَاءٌ مِنْ كُلِّ دَاءٍ إِلَّا السَّامَ قَالُوا يَا رَسُولَ اللَّهِ وَمَا السَّامُ قَالَ الْمَوْتُ ‏","","",""],[23981,23981,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏مُغِيرَةُ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏اسْتَرَاثَ ‏ ‏الْخَبَرَ تَمَثَّلَ فِيهِ بِبَيْتِ ‏ ‏طَرَفَةَ ‏ ‏وَيَأْتِيكَ بِالْأَخْبَارِ مَنْ لَمْ ‏ ‏تُزَوِّدِ ‏","","",""],[23982,23982,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنَامُ وَهُوَ ‏ ‏جُنُبٌ ‏ ‏وَلَا يَمَسُّ مَاءً ‏","","",""],[23983,23983,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏لَمِيسَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ قُلْتُ لَهَا الْمَرْأَةُ تَصْنَعُ الدُّهْنَ ‏ ‏تَحَبَّبُ إِلَى زَوْجِهَا فَقَالَتْ ‏ ‏أَمِيطِي ‏ ‏عَنْكِ تِلْكَ الَّتِي لَا يَنْظُرُ اللَّهُ عَزَّ وَجَلَّ إِلَيْهَا قَالَتْ وَقَالَتْ امْرَأَةٌ ‏ ‏لِعَائِشَةَ ‏ ‏يَا ‏ ‏أُمَّهْ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏إِنِّي لَسْتُ بِأُمِّكُنَّ وَلَكِنِّي أُخْتُكُنَّ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْلِطُ الْعِشْرِينَ بِصَلَاةٍ وَنَوْمٍ فَإِذَا كَانَ الْعَشْرُ شَمَّرَ وَشَدَّ ‏ ‏الْمِئْزَرَ ‏ ‏وَشَمَّرَ ‏","","",""],[23984,23984,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَبْرِ بْنِ حَبِيبٍ ‏ ‏عَنْ ‏ ‏أُمِّ كُلْثُومٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏دَخَلَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَرَادَ أَنْ يُكَلِّمَهُ ‏ ‏وَعَائِشَةُ ‏ ‏تُصَلِّي فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْكِ ‏ ‏بِالْكَوَامِلِ ‏ ‏أَوْ كَلِمَةً أُخْرَى ‏ ‏فَلَمَّا انْصَرَفَتْ ‏ ‏عَائِشَةُ ‏ ‏سَأَلَتْهُ عَنْ ذَلِكَ فَقَالَ لَهَا قُولِي ‏ ‏اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ الْخَيْرِ كُلِّهِ عَاجِلِهِ وَآجِلِهِ مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ وَأَعُوذُ بِكَ مِنْ الشَّرِّ كُلِّهِ عَاجِلِهِ وَآجِلِهِ مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ وَأَسْأَلُكَ الْجَنَّةَ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ وَأَعُوذُ بِكَ مِنْ النَّارِ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ وَأَسْأَلُكَ مِنْ الْخَيْرِ مَا سَأَلَكَ عَبْدُكَ وَرَسُولُكَ ‏ ‏مُحَمَّدٌ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَسْتَعِيذُكَ مِمَّا اسْتَعَاذَكَ مِنْهُ عَبْدُكَ وَرَسُولُكَ ‏ ‏مُحَمَّدٌ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَسْأَلُكَ مَا قَضَيْتَ لِي مِنْ أَمْرٍ أَنْ تَجْعَلَ عَاقِبَتَهُ رَشَدًا ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏جَبْرُ بْنُ حَبِيبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أُمَّ كُلْثُومٍ بِنْتَ أَبِي بَكْرٍ ‏ ‏تُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهَا عَلَيْكِ ‏ ‏بِالْجَوَامِعِ ‏ ‏الْكَوَامِلِ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏جَبْرُ بْنُ حَبِيبٍ ‏ ‏عَنْ ‏ ‏أُمِّ كُلْثُومٍ بِنْتِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[23985,23985,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يِسَافٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏فَقَدْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَظَنَنْتُ أَنَّهُ أَتَى بَعْضَ ‏ ‏جَوَارِيهِ ‏ ‏فَطَلَبْتُهُ فَإِذَا هُوَ سَاجِدٌ يَقُولُ ‏ ‏رَبِّ اغْفِرْ لِي مَا أَسْرَرْتُ وَمَا أَعْلَنْتُ ‏","","",""],[23986,23986,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عُمَارَةَ يَعْنِي ابْنَ أَبِي حَفْصَةَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَوْبَانِ ‏ ‏عُمَانِيَّانِ ‏ ‏أَوْ ‏ ‏قَطَرِيَّانِ ‏ ‏فَقَالَتْ لَهُ ‏ ‏عَائِشَةُ ‏ ‏إِنَّ هَذَيْنِ ثَوْبَانِ غَلِيظَانِ تَرْشَحُ فِيهِمَا فَيَثْقُلَانِ عَلَيْكَ وَإِنَّ فُلَانًا قَدْ جَاءَهُ ‏ ‏بَزٌّ ‏ ‏فَابْعَثْ إِلَيْهِ يَبِيعُكَ ثَوْبَيْنِ إِلَى الْمَيْسَرَةِ قَالَ قَدْ عَرَفْتُ مَا يُرِيدُ ‏ ‏مُحَمَّدٌ ‏ ‏إِنَّمَا يُرِيدُ أَنْ يَذْهَبَ بِثَوْبَيَّ أَيْ لَا ‏ ‏يُعْطِينِي دَرَاهِمِي فَبَلَغَ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏أُرَاهُ قَالَ قَدْ كَذَبَ ‏ ‏لَقَدْ عَرَفُوا أَنِّي أَتْقَاهُمْ لِلَّهِ عَزَّ وَجَلَّ ‏ ‏أَوْ قَالَ أَصْدَقُهُمْ حَدِيثًا ‏ ‏وَآدَاهُمْ لِلْأَمَانَةِ ‏","","",""],[23987,23987,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ رَبٍّ يَعْنِي ابْنَ سَعِيدٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏سَائِبَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ بِقَتْلِ ‏ ‏ذِي الطُّفْيَتَيْنِ ‏ ‏وَالْأَبْتَرِ ‏ ‏وَقَالَ إِنَّهُمَا ‏ ‏يَطْمِسَانِ ‏ ‏الْبَصَرَ وَيُسْقِطَانِ الْوَلَدَ ‏","","",""],[23988,23988,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَرَوْحٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْأَشْعَثِ بْنِ سُلَيْمٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَاهُ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏أَيُّ الْعَمَلِ كَانَ أَحَبَّ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏الدَّائِمُ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏فَقُلْتُ فَأَيُّ حِينٍ كَانَ يَقُومُ قَالَتْ إِذَا سَمِعَ ‏ ‏الصَّارِخَ ‏","","",""],[23989,23989,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْأَشْعَثِ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحِبُّ التَّيَمُّنَ فِي شَأْنِهِ كُلِّهِ ‏ ‏ثُمَّ قَالَ ‏ ‏الْأَشْعَثُ ‏ ‏أَخِيرًا ‏ ‏كَانَ يُحِبُّ التَّيَمُّنَ مَا اسْتَطَاعَ فِي ‏ ‏تَرَجُّلِهِ ‏ ‏وَنَعْلِهِ وَطُهُورِهِ ‏","","",""],[23990,23990,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ الْمُهَاجِرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏صَفِيَّةَ ‏ ‏تحَدَّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏أَسْمَاءَ ‏ ‏سَأَلَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ غُسْلِ الْمَحِيضِ قَالَ ‏ ‏تَأْخُذُ إِحْدَاكُنَّ مَاءَهَا وَسِدْرَتَهَا ‏ ‏فَتَطَهَّرُ فَتُحْسِنُ الطُّهُورَ ثُمَّ تَصُبُّ عَلَى رَأْسِهَا فَتُدَلِّكُهُ دَلْكًا شَدِيدًا حَتَّى يَبْلُغَ شُؤُونَ رَأْسِهَا ثُمَّ تَصُبُّ عَلَيْهَا الْمَاءَ ثُمَّ تَأْخُذُ ‏ ‏فِرْصَةً ‏ ‏مُمَسَّكَةً ‏ ‏فَتَطَهَّرُ بِهَا قَالَتْ ‏ ‏أَسْمَاءُ ‏ ‏وَكَيْفَ ‏ ‏تَطَهَّرُ بِهَا قَالَ سُبْحَانَ اللَّهِ تَطَهَّرِي بِهَا فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏كَأَنَّهَا تُخْفِي ذَلِكَ ‏ ‏تَبْتَغِي ‏ ‏أَثَرَ الدَّمِ وَسَأَلَتْهُ عَنْ غُسْلِ الْجَنَابَةِ قَالَ تَأْخُذِينَ مَاءَكِ ‏ ‏فَتَطَهَّرِينَ فَتُحْسِنِينَ الطُّهُورَ ‏ ‏أَوْ أَبْلِغِي الطُّهُورَ ‏ ‏ثُمَّ تَصُبُّ عَلَى رَأْسِهَا فَتُدَلِّكُهُ حَتَّى يَبْلُغَ شُؤُونَ رَأْسِهَا ثُمَّ تُفِيضُ عَلَيْهَا الْمَاءَ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏نِعْمَ النِّسَاءُ نِسَاءُ ‏ ‏الْأَنْصَارِ ‏ ‏لَمْ يَكُنْ يَمْنَعُهُنَّ الْحَيَاءُ أَنْ يَتَفَقَّهْنَ فِي الدِّينِ ‏","","",""],[23991,23991,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُطَرِّفِ بْنِ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ فِي سُجُودِهِ وَرُكُوعِهِ سُبُّوحٌ قُدُّوسٌ رَبُّ الْمَلَائِكَةِ وَالرُّوحِ ‏","","",""],[23992,23992,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُحَمَّدِ بْنِ الْمُنْتَشِرِ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏أَبَاهُ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَدَعُ أَرْبَعًا قَبْلَ الظُّهْرِ وَرَكْعَتَيْنِ قَبْلَ الصُّبْحِ ‏","","",""],[23993,23993,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَهْدِيٍّ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏مَوْلَى ‏ ‏عُمَرَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كُنْتُ أَنَامُ بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرِجْلَيَّ فِي قِبْلَتِهِ فَإِذَا سَجَدَ غَمَزَنِي فَقَبَضْتُ رِجْلَيَّ وَإِذَا قَامَ بَسَطْتُهُمَا وَالْبُيُوتُ لَيْسَ يَوْمَئِذٍ فِيهَا مَصَابِيحُ ‏","","",""],[23994,23994,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِهِ وَهُوَ ‏ ‏شَاكٍ ‏ ‏فَصَلَّى جَالِسًا وَصَلَّى وَرَاءَهُ قَوْمٌ قِيَامًا فَأَشَارَ إِلَيْهِمْ أَنْ اجْلِسُوا فَلَمَّا انْصَرَفَ قَالَ ‏ ‏إِنَّمَا جُعِلَ الْإِمَامُ لِيُؤْتَمَّ بِهِ فَإِذَا رَكَعَ فَارْكَعُوا وَإِذَا رَفَعَ فَارْفَعُوا وَإِذَا صَلَّى جَالِسًا فَصَلُّوا جُلُوسًا ‏","","",""],[23995,23995,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ شَيْبَانَ ‏ ‏عَنْ ‏ ‏أَبِي نَوْفَلٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُتَسَامَعُ عِنْدَهُ الشِّعْرُ فَقَالَتْ كَانَ أَبْغَضَ الْحَدِيثِ إِلَيْهِ ‏","","",""],[23996,23996,"","","‏ ‏وَقَالَ عَنْ ‏ ‏عَائِشَةَ ‏ ‏كَانَ ‏ ‏يُعْجِبُهُ ‏ ‏الْجَوَامِعُ ‏ ‏مِنْ الدُّعَاءِ وَيَدَعُ مَا بَيْنَ ذَلِكَ ‏","","",""],[23997,23997,"","","‏ ‏قَالَ وَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏إِذَا ذُكِرَ الصَّالِحُونَ ‏ ‏فَحَيَّهَلَا ‏ ‏بعُمَرَ ‏","","",""],[23998,23998,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَضَعُ رَأْسَهُ فِي حِجْرِهَا فَيَقْرَأُ الْقُرْآنَ وَهِيَ حَائِضٌ ‏","","",""],[23999,23999,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏بِرْذَوْنٍ ‏ ‏وَعَلَيْهِ عِمَامَةٌ طَرَفُهَا بَيْنَ كَتِفَيْهِ فَسَأَلْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏رَأَيْتِيهِ ذَاكَ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏","","",""],[24000,24000,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏فُلَيْتٍ ‏ ‏حَدَّثَتْنِي ‏ ‏جَسْرَةُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏مَا رَأَيْتُ صَانِعَةَ طَعَامٍ مِثْلَ ‏ ‏صَفِيَّةَ ‏ ‏أَهْدَتْ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَاءً فِيهِ طَعَامٌ فَمَا مَلَكْتُ نَفْسِي أَنْ كَسَرْتُهُ فَقُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏مَا كَفَّارَتُهُ فَقَالَ إِنَاءٌ كَإِنَاءٍ وَطَعَامٌ كَطَعَامٍ ‏","","",""]];
